/**
 * Initializes the calendar application.
 */
export async function initCalendar() {
    try {
        // d3 and CalHeatmap are now loaded globally via script tags
        initCalendarCurrency();

        const { processedData, byDate, rates, monthlyPnl } = await getCalendarData(DATA_PATHS);
        appState.rates = rates;
        appState.monthlyPnl = monthlyPnl instanceof Map ? monthlyPnl : new Map();
        precomputeDisplayCaches(byDate, CURRENCY_SYMBOLS, appState.rates);
        rebuildFetchedMonthIndex(byDate);
        const latestMonthlyKey = getLatestMonthlyKey(appState.monthlyPnl);
        calendarByDate = byDate; // Store globally for resize handling

        const { firstMonthWithLabels, lastDataDate } = computeDataBounds(processedData);
        const todayNy = getNyDate();
        const { lastVisibleMonth, effectiveRange, calendarStartDate } = computeCalendarRangeConfig(
            firstMonthWithLabels,
            lastDataDate,
            todayNy
        );

        if (typeof latestMonthlyKey === 'string') {
            appState.highlightMonthKey = latestMonthlyKey;
        } else {
            appState.highlightMonthKey = formatMonthKey(lastVisibleMonth);
        }

        const cal = createCalendarRenderer();
        calendarInstance = cal; // Store for resize handling

        setupEventListeners(cal, byDate, appState, CURRENCY_SYMBOLS);

        const valueField = getValueFieldForCurrency(appState.selectedCurrency);
        const paintConfig = buildCalendarPaintConfig({
            processedData,
            effectiveRange,
            valueField,
            calendarStartDate,
            firstMonthWithLabels,
            todayNy,
            lastDataDate,
        });

        // Store the base configuration for resize handling
        basePaintConfig = { ...paintConfig };

        await cal.paint(paintConfig);
        lastFetchedAt = Date.now();
        // The entrance (wrapper slide + nav fade-in) starts only once the
        // initial render — including its staggered passes — has completed, so
        // the CSS transition plays against a settled layout.
        schedulePostPaintUpdates(
            cal,
            calendarByDate,
            appState,
            CURRENCY_SYMBOLS,
            triggerCalendarEntrance
        );
        initCalendarResponsiveHandlers();
    } catch (error) {
        renderCalendarInitError(error);
    }
}

// --- ZOOM PANE: CENTERING + LIQUID GLASS ---
// When the calendar zooms, the pane glides to the viewport center and scales
// as one composited transform (--zoom-center-shift is measured here, in the
// same microtask the class flips, so no intermediate frame paints). The
// refraction lens (bezel distortion + edge caustics) attaches to an unscaled
// overlay element sized to the zoomed bounding box after the transform settles —
// placing backdrop-filter on the transformed wrapper causes Chromium to evaluate
// feImage at unscaled border-box dimensions, cutting the lens off mid-pane.
// Disposed on zoom-out so the unzoomed wrapper stays untouched.
let zoomRefraction = null;
let zoomRefractionTimer = null;
let zoomLensOverlay = null;
const ZOOM_SETTLE_MS = 600; // 0.55s CSS transition + 50ms buffer

function initCalendarZoomPane() {
    const wrapper = document.querySelector(CALENDAR_SELECTORS.pageWrapper);
    if (!wrapper) {
        return;
    }

    const centerZoomedPane = () => {
        // Layout coordinates (offset* ignores transforms), so the measurement
        // is correct even when re-zooming mid-transition.
        let layoutTop = 0;
        let node = wrapper;
        while (node) {
            layoutTop += node.offsetTop;
            node = node.offsetParent;
        }
        const layoutCenterY = layoutTop + wrapper.offsetHeight / 2 - window.scrollY;
        const shiftY = Math.round(window.innerHeight / 2 - layoutCenterY);
        wrapper.style.setProperty('--zoom-center-shift', `${shiftY}px`);
    };

    const updateOverlayGeometry = () => {
        if (!zoomLensOverlay || !wrapper.classList.contains('zoomed')) {
            return;
        }
        const rect = wrapper.getBoundingClientRect();
        zoomLensOverlay.style.left = `${Math.round(rect.left)}px`;
        zoomLensOverlay.style.top = `${Math.round(rect.top)}px`;
        zoomLensOverlay.style.width = `${Math.round(rect.width)}px`;
        zoomLensOverlay.style.height = `${Math.round(rect.height)}px`;
        if (zoomRefraction) {
            zoomRefraction.update();
        }
    };

    const syncZoomRefraction = () => {
        const isZoomed = wrapper.classList.contains('zoomed');
        if (isZoomed && !zoomRefraction && !zoomRefractionTimer) {
            centerZoomedPane();
            zoomRefractionTimer = window.setTimeout(() => {
                zoomRefractionTimer = null;
                if (!wrapper.classList.contains('zoomed')) {
                    return;
                }
                if (!zoomLensOverlay) {
                    zoomLensOverlay = document.createElement('div');
                    zoomLensOverlay.id = 'calendar-zoom-lens';
                    zoomLensOverlay.setAttribute('aria-hidden', 'true');
                    zoomLensOverlay.style.position = 'fixed';
                    zoomLensOverlay.style.pointerEvents = 'none';
                    zoomLensOverlay.style.borderRadius = '8px';
                    zoomLensOverlay.style.zIndex = '99';
                    document.body.appendChild(zoomLensOverlay);
                }
                const rect = wrapper.getBoundingClientRect();
                zoomLensOverlay.style.left = `${Math.round(rect.left)}px`;
                zoomLensOverlay.style.top = `${Math.round(rect.top)}px`;
                zoomLensOverlay.style.width = `${Math.round(rect.width)}px`;
                zoomLensOverlay.style.height = `${Math.round(rect.height)}px`;
                try {
                    zoomRefraction = new LiquidGlassRefraction(
                        zoomLensOverlay,
                        CALENDAR_ZOOM_REFRACTION
                    );
                } catch (e) {
                    logger.error('Failed to initialize zoom pane effects:', e);
                    zoomRefraction = null;
                }
            }, ZOOM_SETTLE_MS);
        } else if (!isZoomed) {
            if (zoomRefractionTimer) {
                window.clearTimeout(zoomRefractionTimer);
                zoomRefractionTimer = null;
            }
            if (zoomRefraction) {
                zoomRefraction.dispose();
                zoomRefraction = null;
            }
            if (zoomLensOverlay) {
                zoomLensOverlay.remove();
                zoomLensOverlay = null;
            }
        }
    };

    const handleResize = () => {
        if (wrapper.classList.contains('zoomed')) {
            centerZoomedPane();
            updateOverlayGeometry();
        }
    };
    window.addEventListener('resize', handleResize);

    const observer = new window.MutationObserver(syncZoomRefraction);
    observer.observe(wrapper, {
        attributes: true,
        attributeFilter: ['class'],
    });

    syncZoomRefraction();

    window.addEventListener('beforeunload', () => {
        observer.disconnect();
        window.removeEventListener('resize', handleResize);
        if (zoomRefractionTimer) {
            window.clearTimeout(zoomRefractionTimer);
            zoomRefractionTimer = null;
        }
        if (zoomRefraction) {
            zoomRefraction.dispose();
            zoomRefraction = null;
        }
        if (zoomLensOverlay) {
            zoomLensOverlay.remove();
            zoomLensOverlay = null;
        }
    });
}

