    if (!document.hidden) {
        await refreshPortfolioData();
    }
});

// Refresh when iOS PWA is foregrounded from background (more reliable than visibilitychange on iOS)
window.addEventListener('pageshow', async (event) => {
    if (event.persisted) {
        await refreshPortfolioData();
    }
});

