function updatePointerState(state, chart, options) {
    const target = chart.glassPointerTarget || { x: 0, y: 0 };
    const damping = options.parallax?.damping ?? 0.18;
    state.pointerTarget.x = Math.max(-1.5, Math.min(1.5, target.x || 0));
    state.pointerTarget.y = Math.max(-1.5, Math.min(1.5, target.y || 0));
    state.pointerSmoothed.x += (state.pointerTarget.x - state.pointerSmoothed.x) * damping;
    state.pointerSmoothed.y += (state.pointerTarget.y - state.pointerSmoothed.y) * damping;
}

function updatePhase(state, options, chart) {
    const perf = typeof globalThis !== 'undefined' ? globalThis.performance : undefined;
    const now = perf && typeof perf.now === 'function' ? perf.now() : Date.now();
    if (state.lastTime === null) {
        state.lastTime = now;
        return 0;
    }
    const delta = (now - state.lastTime) / 1000;
    state.lastTime = now;
    const speed = options.reflection?.speed ?? 0;

    // Keep wrapped phase for other effects that need it
    state.phase = (state.phase + delta * speed) % 1;

    // Keep continuous unwrapped phase for electric trails (NEVER wraps)
    state.continuousPhase = (state.continuousPhase || 0) + delta * speed;

    state.ambientPhase =
        (state.ambientPhase + delta * (options.ambientGlow?.pulseSpeed ?? 0.5)) % 1;

    // Backup phase values to preserve across chart updates
    if (chart) {
        chart._glass3dPhaseBackup = state.phase;
        chart._glass3dAmbientPhaseBackup = state.ambientPhase;
        chart._glass3dContinuousPhaseBackup = state.continuousPhase;
    }

    return delta;
}

function drawShadow(ctx, centerX, centerY, outerRadius, depth, options, pointer, squash) {
    const shadowCfg = options.shadow || {};
    const scaleX = shadowCfg.scaleX ?? 1.1;
    const scaleY = shadowCfg.scaleY ?? 0.45;
    const offsetY = shadowCfg.offsetYPx ?? depth * 0.7;
    const opacity = shadowCfg.opacity ?? 0.22;
    const blur = shadowCfg.blur ?? 28;
    const px = pointer.x * 0.35;

    // --- Contact shadow: sharp, close to the object ---
    const contactBlur = Math.round(blur * 0.3);
    const contactOpacity = opacity * 0.6;
    const contactRadius = outerRadius * 0.88;
    ctx.save();
    ctx.translate(centerX + px, centerY + offsetY * 0.55);
    ctx.scale(scaleX * 0.97, scaleY * squash * 1.05);
    const contactGrad = ctx.createRadialGradient(0, 0, contactRadius * 0.35, 0, 0, contactRadius);
    contactGrad.addColorStop(0, `rgba(0, 0, 0, ${contactOpacity})`);
    contactGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = contactGrad;
    ctx.beginPath();
    ctx.ellipse(0, 0, contactRadius, contactRadius, 0, 0, Math.PI * 2);
    ctx.filter = `blur(${contactBlur}px)`;
    ctx.fill();
    ctx.restore();

    // --- Ambient shadow: soft, diffuse, further out ---
    ctx.save();
    ctx.translate(centerX + px, centerY + offsetY);
    ctx.scale(scaleX, scaleY * squash);
    const radius = outerRadius * 0.92;
    const gradient = ctx.createRadialGradient(0, 0, radius * 0.1, 0, 0, radius);
    gradient.addColorStop(0, `rgba(0, 0, 0, ${opacity})`);
    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.ellipse(0, 0, radius, radius, 0, 0, Math.PI * 2);
    ctx.filter = `blur(${blur}px)`;
    ctx.fill();
    ctx.restore();

    // --- Caustic ring: light focused by refraction through curved glass ---
    // A glass torus bends light inward, creating a bright concentrated ring
    // just inside the shadow boundary.
    const causticRadius = radius * 0.85;
    const causticBlur = Math.round(blur * 0.5);
    const causticOpacity = 0.08;
    ctx.save();
    ctx.translate(centerX + px, centerY + offsetY * 0.9);
    ctx.scale(scaleX, scaleY * squash);
    const causticGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, causticRadius);
    // Hollow center — no light concentration in the middle
    causticGrad.addColorStop(0, 'rgba(140, 200, 255, 0)');
    causticGrad.addColorStop(0.5, 'rgba(140, 200, 255, 0)');
    // Bright ring where refracted light converges
    causticGrad.addColorStop(0.75, `rgba(140, 200, 255, ${causticOpacity})`);
    causticGrad.addColorStop(0.9, `rgba(180, 220, 255, ${causticOpacity * 0.7})`);
    // Fade out at the edge
    causticGrad.addColorStop(1, 'rgba(140, 200, 255, 0)');
    ctx.fillStyle = causticGrad;
    ctx.beginPath();
    ctx.ellipse(0, 0, causticRadius, causticRadius, 0, 0, Math.PI * 2);
    ctx.filter = `blur(${causticBlur}px)`;
    ctx.fill();
    ctx.restore();
}

function computeLightVector(options) {
    const azimuth = (options.light?.azimuthDeg ?? -45) * (Math.PI / 180);
    const elevation = (options.light?.elevationDeg ?? 60) * (Math.PI / 180);
    const cosEl = Math.cos(elevation);
    return {
        x: Math.cos(azimuth) * cosEl,
        y: Math.sin(azimuth) * cosEl,
        z: Math.sin(elevation),
    };
}

function drawSideWall(ctx, arc, depth, options, lightVec, pointer) {
    const { x, y, startAngle, endAngle, outerRadius, innerRadius } = arc.getProps(
        ['x', 'y', 'startAngle', 'endAngle', 'outerRadius', 'innerRadius'],
        true
    );
    const squash = options.squash ?? 1;
    const sliceCenterAngle = (startAngle + endAngle) / 2;
    const lightInfluence = Math.max(
        0,
        lightVec.x * Math.cos(sliceCenterAngle) + lightVec.y * Math.sin(sliceCenterAngle)
    );
    const topOpacity = options.sideOpacity?.top ?? 0.5;
    const bottomOpacity = options.sideOpacity?.bottom ?? 0.18;

    const gradient = ctx.createLinearGradient(
        0,
        y - outerRadius * squash,
        0,
        y + depth + outerRadius * squash
    );
    const highlightBoost = 0.15 * lightInfluence;
    gradient.addColorStop(0, `rgba(255, 255, 255, ${Math.min(0.95, topOpacity + highlightBoost)})`);
    gradient.addColorStop(1, `rgba(0, 0, 0, ${Math.max(0, bottomOpacity - highlightBoost * 0.6)})`);

    const centerX = x + (pointer?.x || 0) * 0.2;
    const centerY = y + (pointer?.y || 0) * 0.25;

    ctx.save();
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.ellipse(
        centerX,
        centerY + depth,
        outerRadius,
        outerRadius * squash,
        0,
        startAngle,
        endAngle
    );
    ctx.ellipse(centerX, centerY, outerRadius, outerRadius * squash, 0, endAngle, startAngle, true);
    ctx.fill('evenodd');

    if (innerRadius > 0) {
        const innerGradient = ctx.createLinearGradient(
            0,
            y - innerRadius * squash,
            0,
            y + depth + innerRadius * squash
        );
        innerGradient.addColorStop(0, `rgba(255, 255, 255, ${0.25 + highlightBoost * 0.5})`);
        innerGradient.addColorStop(1, `rgba(0, 0, 0, ${0.3})`);
        ctx.beginPath();
        ctx.ellipse(
            centerX,
            centerY + depth,
            innerRadius,
            innerRadius * squash,
            0,
            endAngle,
            startAngle,
            true
        );
        ctx.ellipse(centerX, centerY, innerRadius, innerRadius * squash, 0, startAngle, endAngle);
        ctx.fillStyle = innerGradient;
        ctx.fill('evenodd');
    }

    ctx.restore();
}

function drawRimHighlight(ctx, centerX, centerY, outerRadius, innerRadius, options, pointer) {
    const rimCfg = options.rimHighlight || {};
    const width = rimCfg.width ?? 1.2;
    const opacity = rimCfg.opacity ?? 0.3;
    const squash = options.squash ?? 1;
    const px = pointer.x * 0.3;
    const py = pointer.y * 0.3;
    const dispersion = rimCfg.dispersion ?? 10;

    // Chromatic dispersion derived from the electric trail palette
    // so the rim feels part of the same energy system.
    // Outer: sky-blue (from primary 140,205,255), core: pale electric blue,
    // inner: lavender shift (from tertiary 180,140,255).
    const channels = [
        { color: [70, 205, 255], offset: dispersion, opacityScale: 0.08 }, // sky-blue (outer)
        { color: [80, 185, 255], offset: 0, opacityScale: 0.12 }, // electric blue core
        { color: [90, 140, 255], offset: -dispersion, opacityScale: 0.14 }, // lavender (inner)
    ];

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';

    const bandWidth = width * 50;

    for (let i = 0; i < channels.length; i++) {
        const { color, offset, opacityScale } = channels[i];
        const outerR = Math.max(0, outerRadius + offset);
        const innerGradR = Math.max(0, outerR - bandWidth);
        const outerGradR = Math.max(innerGradR + 0.001, outerR + width);
        const gradient = ctx.createRadialGradient(
            centerX + px,
            centerY + py,
            innerGradR,
            centerX + px,
            centerY + py,
            outerGradR
        );
        const [r, g, b] = color;
        const peakOpacity = opacity * opacityScale;
        gradient.addColorStop(0, `rgba(${r}, ${g}, ${b}, 0)`);
        gradient.addColorStop(0.6, `rgba(${r}, ${g}, ${b}, ${peakOpacity})`);
        gradient.addColorStop(0.85, `rgba(${r}, ${g}, ${b}, ${peakOpacity * 0.6})`);
        gradient.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0)`);

        ctx.fillStyle = gradient;
        ctx.beginPath();
        ctx.ellipse(centerX + px, centerY + py, outerR, outerR * squash, 0, 0, Math.PI * 2);
        ctx.ellipse(
            centerX + pointer.x * 0.2,
            centerY + pointer.y * 0.2,
            innerRadius,
            innerRadius * squash,
            0,
            Math.PI * 2,
            0,
            true
        );
        ctx.fill('evenodd');
    }

    ctx.restore();
}

function drawFresnelHighlight(ctx, meta, options, pointer) {
    const squash = options.squash ?? 1;
    const fresnelCfg = options.fresnel || {};
    const baseReflectance = fresnelCfg.r0 ?? 0.04; // glass at normal incidence ~4%
    const intensity = fresnelCfg.intensity ?? 0.35;
    const exponent = fresnelCfg.exponent ?? 5; // Schlick's approximation power
    const lightVec = computeLightVector(options);
    const lightAngle = Math.atan2(lightVec.y, lightVec.x);

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';

    for (let i = 0; i < meta.data.length; i++) {
        const arc = meta.data[i];
        const { x, y, startAngle, endAngle, outerRadius, innerRadius } = arc.getProps(
            ['x', 'y', 'startAngle', 'endAngle', 'outerRadius', 'innerRadius'],
            true
        );

        const midAngle = (startAngle + endAngle) / 2;

        // Schlick's Fresnel approximation for a torus cross-section.
        // The grazing factor measures how edge-on this arc segment is:
        // segments at the sides of the ring (3/9 o'clock) are glancing,
        // segments at top/bottom face the viewer more directly.
        const grazing = 1 - Math.abs(Math.sin(midAngle) * squash);
        const fresnel = baseReflectance + (1 - baseReflectance) * Math.pow(grazing, exponent);

        // Modulate by light direction — segments facing the light get a boost,
        // segments facing away get attenuated. This breaks left/right symmetry.
        const lightDot = 0.5 + 0.5 * Math.cos(midAngle - lightAngle);
        const alpha = fresnel * intensity * (0.4 + 0.6 * lightDot);

        if (alpha < 0.005) {
            return;
        }

        const bandRadius = (outerRadius + innerRadius) / 2;
        const bandWidth = (outerRadius - innerRadius) * 0.5;
        const cx = x + (pointer?.x || 0) * 0.2;
        const cy = y + (pointer?.y || 0) * 0.2;

        ctx.globalAlpha = alpha;
        ctx.strokeStyle = 'rgba(200, 225, 255, 1)';
        ctx.lineWidth = bandWidth;
        ctx.lineCap = 'butt';
        ctx.beginPath();
        ctx.ellipse(cx, cy, bandRadius, bandRadius * squash, 0, startAngle, endAngle);
        ctx.stroke();
    }

    ctx.globalAlpha = 1;
    ctx.restore();
}

function drawTopHighlight(ctx, centerX, centerY, outerRadius, innerRadius, options, pointer) {
    const highlightCfg = options.topHighlight || {};
    const intensity = highlightCfg.intensity ?? 0.4;
    const radiusFraction = highlightCfg.radiusFraction ?? 0.8;
    const squash = options.squash ?? 1;
    const highlightX = centerX - pointer.x * 0.4;
    const highlightY = centerY - outerRadius * 0.35 * squash - pointer.y * 0.3;

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.beginPath();
    // Draw outer circle
    ctx.ellipse(centerX, centerY, outerRadius, outerRadius * squash, 0, 0, Math.PI * 2);
    // Cut out inner circle to create donut shape
    ctx.ellipse(centerX, centerY, innerRadius, innerRadius * squash, 0, Math.PI * 2, 0, true);
    const radius = outerRadius * radiusFraction;
    const gradient = ctx.createRadialGradient(
        highlightX,
        highlightY,
        radius * 0.1,
        highlightX,
        highlightY,
        radius
    );
    gradient.addColorStop(0, `rgba(255, 255, 255, ${intensity})`);
    gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = gradient;
    ctx.fill('evenodd');
    ctx.restore();
}

function drawReflection(ctx, centerX, centerY, outerRadius, innerRadius, options, state) {
    const reflectionCfg = options.reflection || {};
    const intensity = reflectionCfg.intensity ?? 0.28;
    const width = reflectionCfg.width ?? 0.2;
    const phase = state.phase || 0;
    const startAngle = phase * Math.PI * 2;
    const endAngle = startAngle + width * Math.PI * 2;
    const squash = options.squash ?? 1;
    const midRadius = (outerRadius + innerRadius) / 2;
    const bandWidth = (outerRadius - innerRadius) * 0.55;

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';

    // Gaussian beam optics: a specular caustic on curved glass is a sharp core
    // surrounded by a softer bloom halo, with Fresnel blue-shift at grazing edges.
    // 3 smooth passes replicate this layered structure without segmentation seams.

    const passes = [
        // Pass 1 — Bloom halo: wide, soft, white — the diffuse scatter around the caustic
        { widthScale: 1.6, alpha: intensity * 0.25, color: [255, 255, 255] },
        // Pass 2 — Core highlight: sharp, bright, near-white with very subtle blue shift
        { widthScale: 0.7, alpha: intensity, color: [240, 248, 255] },
        // Pass 3 — Fresnel edge: narrow inner rim, blue-tinted — grazing-angle Fresnel reflection
        { widthScale: 0.3, alpha: intensity * 0.4, color: [180, 215, 255] },
    ];

    for (const pass of passes) {
        const lw = Math.max(1, bandWidth * pass.widthScale);
        const [r, g, b] = pass.color;

        // Top-to-bottom gradient: overhead light = bright at top, fade to transparent at bottom
        const gradient = ctx.createLinearGradient(
            0,
            centerY - outerRadius,
            0,
            centerY + outerRadius
        );
        gradient.addColorStop(0, `rgba(${r}, ${g}, ${b}, ${pass.alpha.toFixed(3)})`);
        gradient.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0)`);

        ctx.strokeStyle = gradient;
        ctx.lineWidth = lw;
        ctx.globalAlpha = pass.alpha;

        ctx.beginPath();
        ctx.ellipse(centerX, centerY, midRadius, midRadius * squash, 0, startAngle, endAngle);
        ctx.stroke();
    }

    ctx.restore();
}

function drawSideWalls(ctx, meta, depth, options, lightVec, pointer) {
    for (let i = 0; i < meta.data.length; i++) {
        drawSideWall(ctx, meta.data[i], depth, options, lightVec, pointer);
    }
}

function getOverlayColors(options) {
    const electricColors = options.electric?.colors;
    if (electricColors && typeof electricColors === 'object') {
        const palette = [];
        if (electricColors.primary) {
            palette.push(electricColors.primary);
        }
        if (electricColors.secondary) {
            palette.push(electricColors.secondary);
        }
        if (electricColors.tertiary) {
            palette.push(electricColors.tertiary);
        }
        if (electricColors.quaternary) {
            palette.push(electricColors.quaternary);
        }
        if (Array.isArray(electricColors.list)) {
            palette.push(...electricColors.list);
        }
        if (palette.length > 0) {
            return palette;
        }
    }
    const overlay =
        options.overlayColors ||
        options.distortion?.overlayColors ||
        (typeof window !== 'undefined' &&
            window.pieChartGlassEffect?.liquidGlass?.distortion?.overlayColors);
    if (overlay) {
        return [overlay.inner, overlay.middle, overlay.outer].filter(Boolean);
    }
    return ['rgba(0, 255, 200, 0.6)', 'rgba(0, 180, 255, 0.45)', 'rgba(64, 224, 208, 0.4)'];
}

function initializeEnergyParticles(state, options) {
    const count = Math.max(12, (options.electric?.arcCount || 3) * 8);
    state.energyParticles = Array.from({ length: count }, () => ({
        angle: Math.random() * Math.PI * 2,
        speed: 0.5 + Math.random() * 1.2,
        radiusFactor: 0.75 + Math.random() * 0.2,
        size: 1.2 + Math.random() * 1.6,
        flickerOffset: Math.random() * Math.PI * 2,
    }));
}

function updateEnergyParticles(state, delta, options) {
    if (!state.energyParticles || options.electric?.particlesEnabled === false) {
        if (options.electric?.particlesEnabled === false) {
            state.energyParticles = [];
        }
        return;
    }
    const baseSpeed =
        (options.reflection?.speed ?? 0.05) * (options.electric?.particleSpeedMultiplier ?? 1);
    for (let i = 0; i < state.energyParticles.length; i++) {
        const particle = state.energyParticles[i];
        const variance = 0.8 + (i % 5) * 0.12;
        particle.angle =
            (particle.angle + delta * baseSpeed * 6 * particle.speed * variance) % (Math.PI * 2);
        particle.radiusFactor =
            0.75 + Math.sin(state.phase * Math.PI * 2 + particle.flickerOffset) * 0.05;
    }
}

function computeFresnelAt(angle, squash, fresnelR0, fresnelExp) {
    const grazing = 1 - Math.abs(Math.sin(angle) * squash);
    return fresnelR0 + (1 - fresnelR0) * Math.pow(grazing, fresnelExp);
}

function computeSpecularOverlap(angle, reflStart, reflWidth) {
    // Normalize angle into [0, 2π) range
    const a = ((angle % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
    // Check against the reflection band (which may wrap around 2π)
    const rStart = ((reflStart % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
    const rSpan = reflWidth * Math.PI * 2;
    let dist;
    if (rStart + rSpan <= Math.PI * 2) {
        // Band doesn't wrap
        if (a >= rStart && a <= rStart + rSpan) {
            dist = Math.min(a - rStart, rStart + rSpan - a) / (rSpan * 0.5);
            return 1 - dist;
        }
        return 0;
    }
    // Band wraps around 2π
    if (a >= rStart || a <= (rStart + rSpan) % (Math.PI * 2)) {
        const wrapped = a >= rStart ? a - rStart : a + Math.PI * 2 - rStart;
        dist = Math.min(wrapped, rSpan - wrapped) / (rSpan * 0.5);
        return 1 - Math.max(0, dist);
    }
    return 0;
}

function drawGhostTrailSegments(ctx, p) {
    const {
        cx,
        cy,
        squash,
        ghostRadius,
        segments,
        arcStart,
        arcSpan,
        flareColor,
        color,
        arcThickness,
        pulseBase,
        reflStart,
        reflWidth,
        fresnelBoost,
        fresnelR0,
        fresnelExp,
        ghostOffset,
    } = p;
    for (let s = 0; s < segments; s += 1) {
        const t = (s + 0.5) / segments;
        const segStart = arcStart - ghostOffset + arcSpan * (s / segments);
        const segEnd = arcStart - ghostOffset + arcSpan * ((s + 1) / segments);

        // Asymmetric comet fade: fast rise at head (t≈1), long decay into tail (t≈0)
        const cometFade = Math.pow(t, 0.6) * Math.pow(1 - Math.pow(t, 3), 0.5);
        const segMid = (segStart + segEnd) / 2;
        const flare = computeSpecularOverlap(segMid, reflStart, reflWidth);
        const fresnel = 1 + computeFresnelAt(segMid, squash, fresnelR0, fresnelExp) * fresnelBoost;
        const ghostAlpha = cometFade * (0.2 + flare * 0.3) * pulseBase * fresnel;

        if (ghostAlpha < 0.005) {
            continue;
        }

        const ghostColor = flare > 0.1 ? flareColor : color;
        const ghostWidth = arcThickness * 2.5 * cometFade * (1 + flare * 0.5);

        // Glow pass: wider, dimmer stroke (replaces expensive shadowBlur)
        ctx.strokeStyle = ghostColor;
        ctx.lineWidth = ghostWidth * 3;
        ctx.globalAlpha = ghostAlpha * 0.25;
        ctx.beginPath();
        ctx.ellipse(cx, cy, ghostRadius, ghostRadius * squash, 0, segStart, segEnd);
        ctx.stroke();

        // Core pass
        ctx.lineWidth = ghostWidth;
        ctx.globalAlpha = ghostAlpha;
        ctx.beginPath();
        ctx.ellipse(cx, cy, ghostRadius, ghostRadius * squash, 0, segStart, segEnd);
        ctx.stroke();
    }
}

function drawMainTrailSegments(ctx, p) {
    const {
        cx,
        cy,
        squash,
        trailRadius,
        segments,
        arcStart,
        arcSpan,
        color,
        flareColor,
        headColor,
        tailColor,
        pulseBase,
        pulsePhase,
        reflStart,
        reflWidth,
        fresnelBoost,
        fresnelR0,
        fresnelExp,
        arcThickness,
    } = p;
    for (let s = 0; s < segments; s += 1) {
        const t = (s + 0.5) / segments; // 0 = tail, 1 = head
        const segStart = arcStart + arcSpan * (s / segments);
        const segEnd = arcStart + arcSpan * ((s + 1) / segments);

        // Asymmetric comet envelope: sharp bright head, long diffuse tail
        const cometFade = Math.pow(t, 0.5) * Math.pow(1 - Math.pow(t, 4), 0.4);
        const pulse = pulseBase * (0.85 + 0.15 * Math.sin(t * Math.PI * 6 + pulsePhase));

        // Color temperature: interpolate from tail (cool base color) → head (hot white-blue)
        // Head segments (t > 0.7) shift to hot white, tail stays as the base color
        const headMix = Math.pow(Math.max(0, (t - 0.4) / 0.6), 2);
        const tailMix = Math.pow(Math.max(0, (0.5 - t) / 0.5), 1.5);
        let segColor = color;
        if (headMix > 0.01) {
            segColor = applyAlpha(headColor, headMix * 0.8);
        } else if (tailMix > 0.01) {
            segColor = applyAlpha(tailColor, tailMix * 0.5);
        }

        // Specular flare: boost when crossing the reflection band
        const mainSegMid = (segStart + segEnd) / 2;
        const flare = computeSpecularOverlap(mainSegMid, reflStart, reflWidth);
        // Fresnel modulation: glancing angles on the torus surface reflect more light
        const fresnel =
            1 + computeFresnelAt(mainSegMid, squash, fresnelR0, fresnelExp) * fresnelBoost;
        const alpha = cometFade * pulse * (1 + flare * 1.5) * fresnel;
        const thickness = arcThickness * (0.2 + 0.8 * cometFade) * (1 + flare * 0.4);

        if (alpha < 0.005) {
            continue;
        }

        // Glow pass: wide, dim stroke simulates the blur halo
        const mainColor = flare > 0.15 ? flareColor : color;
        ctx.strokeStyle = mainColor;
        ctx.lineWidth = thickness * (2.5 + headMix * 2 + flare * 3);
        ctx.globalAlpha = alpha * 0.2;
        ctx.beginPath();
        ctx.ellipse(cx, cy, trailRadius, trailRadius * squash, 0, segStart, segEnd);
        ctx.stroke();

        // Core pass: sharp, bright — uses color temperature shift
        ctx.strokeStyle = flare > 0.15 ? flareColor : segColor;
        ctx.lineWidth = thickness;
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.ellipse(cx, cy, trailRadius, trailRadius * squash, 0, segStart, segEnd);
        ctx.stroke();

        // Hot core overlay at the head OR in the specular zone
        if (headMix > 0.05 || flare > 0.2) {
            const coreMix = Math.max(headMix, flare);
            ctx.strokeStyle = flareColor;
            ctx.lineWidth = thickness * (0.4 + flare * 0.3);
            ctx.globalAlpha = alpha * coreMix * 0.9;
            ctx.beginPath();
            ctx.ellipse(cx, cy, trailRadius, trailRadius * squash, 0, segStart, segEnd);
            ctx.stroke();
        }
    }
}

function extractElectricConfig(options) {
    const electric = options.electric || {};
    return {
        arcCount: electric.arcCount ?? 3,
        widthFactor: electric.width ?? 0.22,
        arcThickness: electric.arcThickness ?? 2.4,
        speedMultiplier: electric.streakSpeedMultiplier ?? 1,
    };
}

function extractElectricTrailParams(options, state, pointer, outerRadius, innerRadius) {
    const reflectionCfg = options.reflection || {};
    const fresnelCfg = options.fresnel || {};
    const eConf = extractElectricConfig(options);

    return {
        arcCount: eConf.arcCount,
        widthFactor: eConf.widthFactor,
        arcThickness: eConf.arcThickness,
        speedMultiplier: eConf.speedMultiplier,
        bandThickness: outerRadius - innerRadius,
        baseRadius: innerRadius + (outerRadius - innerRadius) * 0.65,
        offsetX: pointer.x * 0.2,
        offsetY: pointer.y * 0.2,
        segments: 12,
        headColor: 'rgba(220, 240, 255, 1)',
        tailColor: 'rgba(140, 100, 255, 1)',
        flareColor: 'rgba(240, 250, 255, 1)',
        reflWidth: reflectionCfg.width ?? 0.2,
        reflStart: (state.phase || 0) * Math.PI * 2,
        fresnelR0: fresnelCfg.r0 ?? 0.04,
        fresnelExp: fresnelCfg.exponent ?? 5,
        fresnelBoost: fresnelCfg.trailBoost ?? 0.6,
    };
}

function drawElectricTrail(
    ctx,
    centerX,
    centerY,
    outerRadius,
    innerRadius,
    options,
    state,
    pointer,
    squash
) {
    const colors = getOverlayColors(options);
    const p = extractElectricTrailParams(options, state, pointer, outerRadius, innerRadius);

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.lineCap = 'round';

    const cx = centerX + p.offsetX;
    const cy = centerY + p.offsetY;

    for (let i = 0; i < p.arcCount; i += 1) {
        const color = colors[i % colors.length];
        const localPhase = state.continuousPhase * p.speedMultiplier + (i / p.arcCount) * 0.65;
        const arcStart = localPhase * Math.PI * 2;
        const arcSpan = p.widthFactor * Math.PI * 2 * 0.75;

        // Each trail orbits at a slightly different radius (weave within the band)
        const radiusOffset = Math.sin(localPhase * Math.PI * 4 + i * 2.1) * p.bandThickness * 0.08;
        const trailRadius = p.baseRadius + radiusOffset;

        // Energy pulse: sinusoidal throb along the trail phase
        const pulsePhase = state.continuousPhase * 3 + i * 1.7;
        const pulseBase = 0.7 + 0.3 * Math.sin(pulsePhase * Math.PI * 2);

        // --- Ghost afterglow trail (wider, dimmer, slightly behind) ---
        const ghostOffset = arcSpan * 0.15;
        const ghostRadius = trailRadius + p.bandThickness * 0.05 * (i % 2 === 0 ? 1 : -1);

        drawGhostTrailSegments(ctx, {
            cx,
            cy,
            squash,
            ghostRadius,
            segments: p.segments,
            arcStart,
            arcSpan,
            flareColor: p.flareColor,
            color,
            arcThickness: p.arcThickness,
            pulseBase,
            reflStart: p.reflStart,
            reflWidth: p.reflWidth,
            fresnelBoost: p.fresnelBoost,
            fresnelR0: p.fresnelR0,
            fresnelExp: p.fresnelExp,
            ghostOffset,
        });

        // --- Main plasma trail with color temperature shift ---
        drawMainTrailSegments(ctx, {
            cx,
            cy,
            squash,
            trailRadius,
            segments: p.segments,
            arcStart,
            arcSpan,
            color,
            flareColor: p.flareColor,
            headColor: p.headColor,
            tailColor: p.tailColor,
            pulseBase,
            pulsePhase,
            reflStart: p.reflStart,
            reflWidth: p.reflWidth,
            fresnelBoost: p.fresnelBoost,
            fresnelR0: p.fresnelR0,
            fresnelExp: p.fresnelExp,
            arcThickness: p.arcThickness,
        });
    }
    ctx.globalAlpha = 1;
    ctx.restore();
}

function drawEnergyParticles(
    ctx,
    centerX,
    centerY,
    outerRadius,
    innerRadius,
    options,
    state,
    pointer,
    squash
) {
    if (!state.energyParticles || options.electric?.particlesEnabled === false) {
        return;
    }
    const colors =
        options.electric?.particleColors && Array.isArray(options.electric.particleColors)
            ? options.electric.particleColors
            : getOverlayColors(options);
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const bandThickness = outerRadius - innerRadius;
    const baseRadius = innerRadius + bandThickness * 0.65;
    for (let i = 0; i < state.energyParticles.length; i++) {
        const particle = state.energyParticles[i];
        const angle = particle.angle;
        const radius = baseRadius * particle.radiusFactor;
        const x = centerX + Math.cos(angle) * radius + pointer.x * 0.15;
        const y = centerY + Math.sin(angle) * radius * squash + pointer.y * 0.15;
        const flicker = 0.5 + 0.5 * Math.sin(state.phase * Math.PI * 4 + particle.flickerOffset);
        const color = colors[i % colors.length] || 'rgba(0,255,255,0.6)';
        const pSize = particle.size + flicker * 1.5;
        // Glow halo: larger, dimmer ellipse (replaces expensive shadowBlur)
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.15 * flicker;
        ctx.beginPath();
        ctx.ellipse(x, y, pSize * 2.5, pSize * 1.5, angle, 0, Math.PI * 2);
        ctx.fill();

        // Core particle
        ctx.globalAlpha = 0.6 + 0.4 * flicker;
        ctx.beginPath();
        ctx.ellipse(x, y, pSize, (particle.size + flicker) * 0.6, angle, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.restore();
}

function drawBeerLambertOverlay(ctx, meta, options) {
    const lightVec = computeLightVector(options);
    const lightAngle = Math.atan2(lightVec.y, lightVec.x);
    const highlightOpacity = 0.18;
    const shadowOpacity = 0.14;

    ctx.save();
    for (let i = 0; i < meta.data.length; i++) {
        const arc = meta.data[i];
        const { x, y, startAngle, endAngle, outerRadius, innerRadius } = arc.getProps(
            ['x', 'y', 'startAngle', 'endAngle', 'outerRadius', 'innerRadius'],
            true
        );

        // Gradient runs from the light direction toward the opposite side
        const gradX1 = x + Math.cos(lightAngle) * outerRadius;
        const gradY1 = y + Math.sin(lightAngle) * outerRadius;
        const gradX2 = x - Math.cos(lightAngle) * outerRadius;
        const gradY2 = y - Math.sin(lightAngle) * outerRadius;

        const gradient = ctx.createLinearGradient(gradX1, gradY1, gradX2, gradY2);
        // Light-facing side: slight white wash (less absorption path)
        gradient.addColorStop(0, `rgba(255, 255, 255, ${highlightOpacity})`);
        // Middle: neutral
        gradient.addColorStop(0.45, 'rgba(0, 0, 0, 0)');
        // Shadow side: deeper/darker (longer absorption path through colored glass)
        gradient.addColorStop(1, `rgba(0, 0, 0, ${shadowOpacity})`);

        // Clip to this specific arc slice
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.arc(x, y, outerRadius, startAngle, endAngle);
        ctx.arc(x, y, innerRadius, endAngle, startAngle, true);
        ctx.closePath();
        ctx.clip();

        ctx.fillStyle = gradient;
        ctx.fillRect(x - outerRadius, y - outerRadius, outerRadius * 2, outerRadius * 2);
        ctx.restore();
    }
    ctx.restore();
}

function drawAtmosphericFade(ctx, centerX, centerY, outerRadius, innerRadius, options) {
    const squash = options.squash ?? 1;
    const fadeOpacity = 0.12;

    ctx.save();

    // Clip to the donut ring so the gradient only affects the face
    ctx.beginPath();
    ctx.ellipse(centerX, centerY, outerRadius, outerRadius * squash, 0, 0, Math.PI * 2);
    ctx.ellipse(centerX, centerY, innerRadius, innerRadius * squash, 0, Math.PI * 2, 0, true);
    ctx.clip('evenodd');

    // Top-to-bottom gradient: transparent at top (near edge), dark at bottom (far edge)
    const gradient = ctx.createLinearGradient(
        centerX,
        centerY - outerRadius * squash,
        centerX,
        centerY + outerRadius * squash
    );
    gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
    gradient.addColorStop(0.5, 'rgba(0, 0, 0, 0)');
    gradient.addColorStop(1, `rgba(0, 0, 0, ${fadeOpacity})`);

    ctx.fillStyle = gradient;
    ctx.fillRect(
        centerX - outerRadius,
        centerY - outerRadius * squash,
        outerRadius * 2,
        outerRadius * squash * 2
    );
    ctx.restore();
}

function drawAmbientGlow(ctx, centerX, centerY, outerRadius, innerRadius, options, state, squash) {
    const glow = options.ambientGlow || {};
    const innerOpacity = glow.innerOpacity ?? 0.2;
    const outerOpacity = glow.outerOpacity ?? 0.05;
    const pulse = 0.5 + 0.5 * Math.sin(state.ambientPhase * Math.PI * 2);

    ctx.save();

    // Clip to exact donut boundaries to prevent glow bleeding
    ctx.beginPath();
    ctx.ellipse(centerX, centerY, outerRadius, outerRadius * squash, 0, 0, Math.PI * 2);
    ctx.ellipse(centerX, centerY, innerRadius, innerRadius * squash, 0, Math.PI * 2, 0, true);
    ctx.clip('evenodd');

    ctx.globalCompositeOperation = 'screen';

    // Use outerRadius as max extent instead of exceeding it
    const gradientRadius = outerRadius * (0.9 + pulse * 0.1);
    const gradient = ctx.createRadialGradient(
        centerX,
        centerY,
        innerRadius,
        centerX,
        centerY,
        gradientRadius
    );
    const innerColor = applyAlpha(glow.innerColor, innerOpacity * (0.6 + pulse * 0.4));
    const outerColor = applyAlpha(glow.outerColor, outerOpacity);
    gradient.addColorStop(0, innerColor);
    gradient.addColorStop(1, outerColor);
    ctx.fillStyle = gradient;

    ctx.beginPath();
    // Draw exactly to outer radius, no overflow
    ctx.ellipse(centerX, centerY, outerRadius, outerRadius * squash, 0, 0, Math.PI * 2);
    // Cut out inner circle to create donut shape
    ctx.ellipse(centerX, centerY, innerRadius, innerRadius * squash, 0, Math.PI * 2, 0, true);
    ctx.fill('evenodd');
    ctx.restore();
}

export const glass3dPlugin = {
    id: 'glass3d',
    beforeDatasetsDraw(chart, args, pluginOptions) {
        const options = resolveOptions(pluginOptions);
        if (!options.enabled) {
            return;
        }
        const meta = chart.getDatasetMeta(0);
        if (!meta || !meta.data || meta.data.length === 0) {
            return;
        }
        const ctx = chart.ctx;
        const firstArc = meta.data[0];
        const {
            x: centerX,
            y: centerY,
            outerRadius,
            innerRadius,
        } = firstArc.getProps(['x', 'y', 'outerRadius', 'innerRadius'], true);
        const depthValue = resolveResponsive(options.depth);
        const depth = depthValue !== undefined ? depthValue : Math.max(outerRadius * 0.12, 12);
        const state = ensureState(chart, options);
        updatePointerState(state, chart, options);
        const delta = updatePhase(state, options, chart);
        updateEnergyParticles(state, delta, options);
        const pointer = {
            x: state.pointerSmoothed.x * state.maxOffset,
            y: state.pointerSmoothed.y * state.maxOffset,
        };

        drawShadow(
            ctx,
            centerX,
            centerY,
            outerRadius,
            depth,
            options,
            pointer,
            options.squash ?? 1
        );
        const lightVec = computeLightVector(options);
        drawSideWalls(ctx, meta, depth, options, lightVec, pointer);
        drawRimHighlight(ctx, centerX, centerY, outerRadius, innerRadius, options, pointer);
    },
    afterDatasetsDraw(chart, args, pluginOptions) {
        const options = resolveOptions(pluginOptions);
        if (!options.enabled) {
            return;
        }
        const meta = chart.getDatasetMeta(0);
        if (!meta || !meta.data || meta.data.length === 0) {
            return;
        }
        const ctx = chart.ctx;
        const firstArc = meta.data[0];
        const {
            x: centerX,
            y: centerY,
            outerRadius,
            innerRadius,
        } = firstArc.getProps(['x', 'y', 'outerRadius', 'innerRadius'], true);
        const state = ensureState(chart, options);
        const pointer = {
            x: state.pointerSmoothed.x * state.maxOffset,
            y: state.pointerSmoothed.y * state.maxOffset,
        };

        drawBeerLambertOverlay(ctx, meta, options);
        drawAtmosphericFade(ctx, centerX, centerY, outerRadius, innerRadius, options);
        drawFresnelHighlight(ctx, meta, options, pointer);
        drawAmbientGlow(
            ctx,
            centerX,
            centerY,
            outerRadius,
            innerRadius,
            options,
            state,
            options.squash ?? 1
        );
        drawElectricTrail(
            ctx,
            centerX,
            centerY,
            outerRadius,
            innerRadius,
            options,
            state,
            pointer,
            options.squash ?? 1
        );
        if (options.electric?.particlesEnabled !== false) {
            drawEnergyParticles(
                ctx,
                centerX,
                centerY,
                outerRadius,
                innerRadius,
                options,
                state,
                pointer,
                options.squash ?? 1
            );
        }
        drawTopHighlight(ctx, centerX, centerY, outerRadius, innerRadius, options, pointer);
        drawReflection(ctx, centerX, centerY, outerRadius, innerRadius, options, state);
    },
};

const DEFAULT_OPTIONS = {
    enabled: true,
    tailRatio: 0.12,
    tailOpacity: 0.85,
    shadowOpacity: 0.45,
    mobileShadowBlur: 4,
    desktopShadowBlur: 12,
    mobileHaloBase: 5.5,
    desktopHaloBase: 7,
    mobileHaloOscillation: 2.2,
    desktopHaloOscillation: 3.5,
    oscillationSpeed: 4,
    phaseOffsetStep: 0.85,
    minPulseRadius: 0.5,
    maxDelta: 0.12,
};

function createAnimationState() {
    return {
        handle: null,
        lastFrameTs: null,
        phase: 0,
    };
}

function clamp(value, min, max) {
    return Math.min(Math.max(value, min), max);
}

function mergeChartSettings(base, override = {}) {
    return {
        tailRatio: override.tailRatio ?? base.tailRatio,
        tailOpacity: override.tailOpacity ?? base.tailOpacity,
        shadowOpacity: override.shadowOpacity ?? base.shadowOpacity,
        mobileShadowBlur: override.mobileShadowBlur ?? base.mobileShadowBlur,
        desktopShadowBlur: override.desktopShadowBlur ?? base.desktopShadowBlur,
        mobileHaloBase: override.mobileHaloBase ?? base.mobileHaloBase,
        desktopHaloBase: override.desktopHaloBase ?? base.desktopHaloBase,
        mobileHaloOscillation: override.mobileHaloOscillation ?? base.mobileHaloOscillation,
        desktopHaloOscillation: override.desktopHaloOscillation ?? base.desktopHaloOscillation,
        oscillationSpeed: override.oscillationSpeed ?? base.oscillationSpeed,
        phaseOffsetStep: override.phaseOffsetStep ?? base.phaseOffsetStep,
        minPulseRadius: override.minPulseRadius ?? base.minPulseRadius,
        maxDelta: override.maxDelta ?? base.maxDelta,
    };
}

function hexToRgb(color) {
    if (!color) {
        return null;
    }
    const trimmed = color.trim();

    if (trimmed.startsWith('rgb')) {
        const match = trimmed.replace(/\s+/g, '').match(/rgba?\((\d+),(\d+),(\d+)/i);
        if (match) {
            return {
                r: Number.parseInt(match[1], 10),
                g: Number.parseInt(match[2], 10),
                b: Number.parseInt(match[3], 10),
            };
        }
    }

    let hex = trimmed;
    if (hex.startsWith('#')) {
        hex = hex.slice(1);
    }
    if (hex.length === 3) {
        hex = hex
            .split('')
            .map((char) => char + char)
            .join('');
    }
    if (hex.length !== 6) {
        return null;
    }
    const num = Number.parseInt(hex, 16);
    if (Number.isNaN(num)) {
        return null;
    }
    return {
        r: (num >> 16) & 255,
        g: (num >> 8) & 255,
        b: num & 255,
    };
}

function drawGlow(ctx, series, options, settings) {
    const { coords, color, lineWidth } = series;
    if (!coords || coords.length === 0) {
        return;
    }

    const { isMobile = false, basePhase = 0, seriesIndex = 0 } = options;
    const rgb = hexToRgb(color);
    if (!rgb) {
        return;
    }

    const appliedPhase = basePhase + seriesIndex * settings.phaseOffsetStep;
    const oscillation = 0.5 + 0.5 * Math.sin(appliedPhase * settings.oscillationSpeed);
    const minPulseRadius = Math.max(settings.minPulseRadius, lineWidth / 2);
    const haloBase = isMobile ? settings.mobileHaloBase : settings.desktopHaloBase;
    const haloOscillation = isMobile
        ? settings.mobileHaloOscillation
        : settings.desktopHaloOscillation;
    const haloRadius = minPulseRadius + haloBase + oscillation * haloOscillation;

    const tailCount =
        settings.tailRatio > 0 ? Math.max(2, Math.floor(coords.length * settings.tailRatio)) : 0;
    if (tailCount > 1) {
        const tailPoints = coords.slice(-tailCount);
        const start = tailPoints[0];
        const end = tailPoints[tailPoints.length - 1];

        if (start.x !== end.x || start.y !== end.y) {
            const gradient = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
            gradient.addColorStop(0, `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0)`);
            gradient.addColorStop(1, `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${settings.tailOpacity})`);

            ctx.save();
            ctx.lineWidth = lineWidth;
            ctx.strokeStyle = gradient;
            ctx.shadowColor = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${settings.shadowOpacity})`;
            ctx.shadowBlur = isMobile ? settings.mobileShadowBlur : settings.desktopShadowBlur;
            ctx.beginPath();
            for (let i = 0; i < tailPoints.length; i++) {
                const point = tailPoints[i];
                if (i === 0) {
                    ctx.moveTo(point.x, point.y);
                } else {
                    ctx.lineTo(point.x, point.y);
                }
            }
            ctx.stroke();
            ctx.restore();
        }
    }

    const gradient = ctx.createRadialGradient(
        coords[coords.length - 1].x,
        coords[coords.length - 1].y,
        minPulseRadius * 0.6,
        coords[coords.length - 1].x,
        coords[coords.length - 1].y,
        haloRadius
    );
    gradient.addColorStop(0, `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.96)`);
    gradient.addColorStop(0.35, `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.35)`);
    gradient.addColorStop(1, `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0)`);

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(coords[coords.length - 1].x, coords[coords.length - 1].y, haloRadius, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.95)`;
    ctx.beginPath();
    ctx.arc(
        coords[coords.length - 1].x,
        coords[coords.length - 1].y,
        minPulseRadius,
        0,
        Math.PI * 2
    );
    ctx.fill();

    const ringRadius = minPulseRadius + Math.min(minPulseRadius * 0.4, 0.5);
    ctx.strokeStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.55)`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(coords[coords.length - 1].x, coords[coords.length - 1].y, ringRadius, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.shadowColor = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${settings.shadowOpacity})`;
    const glowBlur = (isMobile ? settings.mobileShadowBlur : settings.desktopShadowBlur) * 0.8;
    ctx.shadowBlur = glowBlur;
    ctx.globalAlpha = clamp(0.6 + 0.4 * oscillation, 0.25, 1);
    ctx.fillStyle = `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, 0.35)`;
    ctx.beginPath();
    ctx.arc(
        coords[coords.length - 1].x,
        coords[coords.length - 1].y,
        minPulseRadius + 1.8,
        0,
        Math.PI * 2
    );
    ctx.fill();
    ctx.restore();
}

export function createGlowTrailAnimator(options = {}) {
    const baseConfig = {
        ...DEFAULT_OPTIONS,
        ...options,
        charts: options.charts || {},
    };

    const states = new Map();

    function ensureState(key) {
        if (!states.has(key)) {
            states.set(key, createAnimationState());
        }
        return states.get(key);
    }

    function getChartSettings(chartKey) {
        const override = baseConfig.charts?.[chartKey] || {};
        return mergeChartSettings(baseConfig, override);
    }

    function isEnabledFor(chartKey) {
        if (baseConfig.enabled === false) {
            return false;
        }
        const override = baseConfig.charts?.[chartKey];
        if (override && override.enabled === false) {
            return false;
        }
        return true;
    }

    function stop(key) {
        const state = states.get(key);
        if (!state) {
            return;
        }
        if (state.handle !== null) {
            cancelAnimationFrame(state.handle);
            state.handle = null;
        }
        state.lastFrameTs = null;
        state.phase = 0;
    }

    function stopAll() {
        for (const key of states.keys()) {
            stop(key);
        }
    }

    function schedule(key, chartManager, { isActive } = {}) {
        const state = ensureState(key);
        if (state.handle !== null) {
            return;
        }
        state.handle = requestAnimationFrame((timestamp) => {
            state.handle = null;
            if (typeof isActive === 'function' && !isActive()) {
                stop(key);
                return;
            }
            chartManager.redraw(timestamp);
        });
    }

    function advance(key, timestamp) {
        const state = ensureState(key);
        const settings = getChartSettings(key);
        const nowFn = () => {
            if (typeof globalThis !== 'undefined' && globalThis.performance) {
                return globalThis.performance.now();
            }
            if (typeof window !== 'undefined' && window.performance) {
                return window.performance.now();
            }
            return Date.now();
        };
        const ts = typeof timestamp === 'number' ? timestamp : nowFn();
        if (state.lastFrameTs === null) {
            state.lastFrameTs = ts;
            return state.phase;
        }
        const maxDelta = settings.maxDelta ?? baseConfig.maxDelta;
        const delta = Math.min((ts - state.lastFrameTs) / 1000, maxDelta);
        state.lastFrameTs = ts;
        state.phase = (state.phase + delta) % (Math.PI * 2);
        return state.phase;
    }

    function drawSeriesGlow(ctx, series, drawOptions = {}) {
        const settings = getChartSettings(drawOptions.chartKey);
        drawGlow(ctx, series, drawOptions, settings);
    }

    return {
        isEnabledFor,
        schedule,
        stop,
        stopAll,
        advance,
        drawSeriesGlow,
    };
}

import { easeInOutSine } from '@utils/easing.js';
import { PLUGIN_CONFIGS } from '@js/config.js';

// --- Wave Animation Plugin Helpers ---
function _startWaveAnimation(chart) {
    const animState = chart.waveAnimation;
    if (animState.animationFrameId) {
        return;
    } // Already running

    const animate = () => {
        if (!chart.canvas || !document.body.contains(chart.canvas)) {
            // Stop if chart is gone
            _stopWaveAnimation(chart);
            return;
        }

        const meta = chart.getDatasetMeta(0);
        // let currentInnerRadiusValue = 0; // Not directly used for outward expansion logic here
        let currentOuterRadiusValue = 0;
        if (meta && meta.data && meta.data.length) {
            // currentInnerRadiusValue = meta.data[0].innerRadius;
            currentOuterRadiusValue = meta.data[0].outerRadius;
        }

        // Stop if no outer edge (e.g. chart cleared) and no waves left to animate
        if (currentOuterRadiusValue <= 0 && animState.waves.length === 0) {
            _stopWaveAnimation(chart);
            return;
        }

        // Update wave states, pass outerRadius for spawning waves from the outside
        updateWaveState(chart, currentOuterRadiusValue > 0 ? currentOuterRadiusValue : 0);
        chart.draw(); // Redraw the chart to show updated waves

        // Only continue animation if there are active waves or potential to spawn new ones
        if (
            animState.waves.length > 0 ||
            (currentOuterRadiusValue > 0 && animState.waves.length < animState.config.MAX_WAVES)
        ) {
            animState.animationFrameId = requestAnimationFrame(animate);
        } else {
            _stopWaveAnimation(chart); // No waves and no way to make new ones
        }
    };
    animState.animationFrameId = requestAnimationFrame(animate);
}

function _stopWaveAnimation(chart) {
    const animState = chart.waveAnimation;
    if (animState && animState.animationFrameId) {
        cancelAnimationFrame(animState.animationFrameId);
        animState.animationFrameId = null;
    }
}

function updateWaveState(chart, currentOuterRadiusValue) {
    const animState = chart.waveAnimation;
    if (!animState) {
        return;
    }

    const config = animState.config;
    const now = Date.now();

    // Spawn new waves if conditions are met
    if (
        currentOuterRadiusValue > 0 &&
        now - animState.lastSpawnTime > config.SPAWN_INTERVAL &&
        animState.waves.length < config.MAX_WAVES
    ) {
        animState.waves.push({
            radius: currentOuterRadiusValue,
            opacity: config.spawnOpacity,
            spawnRadius: currentOuterRadiusValue,
            targetRadius: currentOuterRadiusValue + config.EXPANSION_DISTANCE,
        });
        animState.lastSpawnTime = now;
    }

    // Update and filter existing waves
    animState.waves = animState.waves.filter((wave) => {
        wave.radius += config.SPEED; // Expand the wave outwards

        // Adjust opacity: fade out as it expands from spawnRadius to targetRadius
        const { SPAWN_OPACITY, EXPANSION_DISTANCE } = config;
        if (EXPANSION_DISTANCE > 0) {
            let progress = 0;
            if (typeof wave.spawnRadius === 'number') {
                progress = Math.min(
                    1,
                    Math.max(0, (wave.radius - wave.spawnRadius) / EXPANSION_DISTANCE)
                );
            } else {
                progress = 1; // Fallback: if spawnRadius is missing, assume fully progressed
            }
            const easedProgress = easeInOutSine(progress);
            wave.opacity = SPAWN_OPACITY * (1 - easedProgress); // Fade from spawnOpacity to 0
        } else {
            wave.opacity = 0; // If no expansion distance, fade out immediately
        }

        // Keep wave if it's still visible and large enough
        return wave.radius < wave.targetRadius && wave.opacity > config.TARGET_OPACITY_FADE;
    });
}

function _manageAnimationState(chart, animState, outerRadius) {
    if (!animState.animationFrameId && outerRadius > 0) {
        _startWaveAnimation(chart);
    } else if (animState.animationFrameId && outerRadius <= 0 && animState.waves.length === 0) {
        _stopWaveAnimation(chart);
    }
}

function _applyWaveClipping(ctx, width, height, centerX, centerY, outerRadius) {
    if (outerRadius > 0 && centerX && centerY) {
        ctx.beginPath();
        ctx.rect(0, 0, width, height);
        ctx.arc(centerX, centerY, outerRadius, 0, Math.PI * 2, true);
        ctx.clip('evenodd');
    }
}

function _drawSingleWave(ctx, wave, centerX, centerY, rgb, outerRadius) {
    if (wave.radius > outerRadius + 3 && wave.opacity > 0 && centerX && centerY) {
        const r = wave.radius;
        const grad = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, r);
        const op = wave.opacity;
        grad.addColorStop(0, `rgba(${rgb}, ${op.toFixed(3)})`);
        grad.addColorStop(0.85, `rgba(${rgb}, ${op.toFixed(3)})`);
        grad.addColorStop(0.95, `rgba(${rgb}, ${Math.min(1, op * 1.4).toFixed(3)})`);
        grad.addColorStop(1, `rgba(${rgb}, 0)`);

        ctx.beginPath();
        ctx.arc(centerX, centerY, r, 0, Math.PI * 2);
        ctx.fillStyle = grad;
        ctx.fill();

        ctx.beginPath();
        ctx.arc(centerX, centerY, r, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(160, 210, 255, ${(op * 0.35).toFixed(3)})`;
        ctx.lineWidth = 1.5;
        ctx.stroke();
    }
}

export const waveAnimationPlugin = {
    id: 'waveCenterAnimation',
    beforeInit: function (chart) {
        // Use the imported configuration
        chart.waveAnimation = {
            waves: [],
            lastSpawnTime: 0,
            animationFrameId: null,
            config: PLUGIN_CONFIGS.WAVE_ANIMATION,
        };
    },
    afterDestroy: function (chart) {
        _stopWaveAnimation(chart);
    },
    // Public method to force start animation (can trigger line 7 defensive check)
    forceStartAnimation: function (chart) {
        if (chart.waveAnimation) {
            _startWaveAnimation(chart);
        }
    },
    beforeDatasetsDraw: function (chart) {
        if (chart.config.type !== 'doughnut' || !chart.waveAnimation) {
            return;
        }

        const animState = chart.waveAnimation;
        const meta = chart.getDatasetMeta(0);
        let outerRadius = 0,
            centerX = 0,
            centerY = 0;
        if (meta && meta.data && meta.data[0]) {
            outerRadius = meta.data[0].outerRadius || 0;
            centerX = meta.data[0].x || 0;
            centerY = meta.data[0].y || 0;
        }

        _manageAnimationState(chart, animState, outerRadius);

        const { ctx } = chart;
        ctx.save();

        _applyWaveClipping(ctx, chart.width, chart.height, centerX, centerY, outerRadius);

        for (let i = 0; i < animState.waves.length; i++) {
            _drawSingleWave(
                ctx,
                animState.waves[i],
                centerX,
                centerY,
                animState.config.BASE_COLOR_RGB_TRIPLET,
                outerRadius
            );
        }

        ctx.restore();
    },
};

import { getNyDate, isTradingDay } from '@utils/date.js';
import { formatCurrency } from '@utils/formatting.js';
import { getBlueColorForSlice, hexToRgba } from '@utils/colors.js';
