function _renderPnlSummary(
    totalPnlUSD,
    totalPortfolioValueUSD,
    currentCurrency,
    exchangeRates,
    currencySymbols,
    totalDayChangeUSD = null
) {
    const totalPortfolioCostUSD = totalPortfolioValueUSD - totalPnlUSD;
    const totalPnlPercentage =
        totalPortfolioCostUSD !== 0 ? (totalPnlUSD / totalPortfolioCostUSD) * 100 : 0;

    const pnlContainer = document.getElementById('table-footer-summary');
    const pnlElement = pnlContainer.querySelector('.total-pnl');

    const formattedPnl = formatCurrency(
        Math.abs(totalPnlUSD),
        currentCurrency,
        exchangeRates,
        currencySymbols
    );
    const pnlSign = totalPnlUSD >= 0 ? '+' : '-';
    const pnlPercentageSign = totalPnlPercentage >= 0 ? '+' : '';

    pnlElement.replaceChildren();

    const openBracket = document.createElement('span');
    openBracket.className = 'pnl-bracket';
    openBracket.textContent = ' (';

    const pnlAmount = document.createElement('span');
    pnlAmount.className = 'pnl-amount';
    pnlAmount.textContent = `${pnlSign}${formattedPnl}`;

    const separator = document.createElement('span');
    separator.className = 'pnl-separator';
    separator.textContent = ', ';

    const pnlPercent = document.createElement('span');
    pnlPercent.className = 'pnl-percent';
    pnlPercent.textContent = `${pnlPercentageSign}${totalPnlPercentage.toFixed(2)}%`;

    const closeBracket = document.createElement('span');
    closeBracket.className = 'pnl-bracket';
    closeBracket.textContent = ')';

    const pnlColor = totalPnlUSD >= 0 ? COLORS.POSITIVE_PNL : COLORS.NEGATIVE_PNL;
    pnlAmount.style.color = pnlColor;
    pnlPercent.style.color = pnlColor;

    const footerTextColor = window.getComputedStyle(pnlContainer).color;
    openBracket.style.color = footerTextColor;
    separator.style.color = footerTextColor;
    closeBracket.style.color = footerTextColor;

    // The all-time bracket gets its own wrapper so the mobile footer toggle
    // can hide just it while the day-change stack stays visible by default.
    const allTimeGroup = document.createElement('span');
    allTimeGroup.className = 'pnl-all-time';
    allTimeGroup.appendChild(openBracket);
    allTimeGroup.appendChild(pnlAmount);
    allTimeGroup.appendChild(separator);
    allTimeGroup.appendChild(pnlPercent);
    allTimeGroup.appendChild(closeBracket);
    pnlElement.appendChild(allTimeGroup);

    // Intraday change as a half-size two-line stack (pct over $) trailing the
    // all-time bracket — same idiom as the day-change tags in the table cells,
    // and small enough that the footer stays one line tall.
    if (Number.isFinite(totalDayChangeUSD)) {
        const previousTotalUSD = totalPortfolioValueUSD - totalDayChangeUSD;
        const dayChangePct =
            previousTotalUSD !== 0 ? (totalDayChangeUSD / previousTotalUSD) * 100 : 0;
        const dayColor =
            totalDayChangeUSD > 0
                ? COLORS.POSITIVE_PNL
                : totalDayChangeUSD < 0
                  ? COLORS.NEGATIVE_PNL
                  : footerTextColor;

        const dayStack = document.createElement('span');
        dayStack.className = 'day-pnl-stack';

        const dayPercent = document.createElement('span');
        dayPercent.className = 'day-pnl-percent';
        dayPercent.textContent = `${dayChangePct >= 0 ? '+' : ''}${dayChangePct.toFixed(2)}%`;
        dayPercent.style.color = dayColor;

        const dayAmount = document.createElement('span');
        dayAmount.className = 'day-pnl-amount';
        dayAmount.textContent = `${totalDayChangeUSD >= 0 ? '+' : '-'}${formatCurrency(
            Math.abs(totalDayChangeUSD),
            currentCurrency,
            exchangeRates,
            currencySymbols
        )}`;
        dayAmount.style.color = dayColor;

        dayStack.appendChild(dayPercent);
        dayStack.appendChild(dayAmount);
        pnlElement.appendChild(dayStack);
    }
}

function _updatePerColumn(marketRatiosByTicker, sortedHoldings) {
    if (!marketRatiosByTicker || !(marketRatiosByTicker instanceof Map)) {
        return;
    }
    const rows = document.querySelectorAll('table tbody tr');
    const holdingByTicker = new Map(sortedHoldings.map((h) => [h.ticker, h]));
    for (let i = 0; i < rows.length; i++) {
        const row = rows[i];
        const ticker = row.dataset.ticker;
        if (!ticker) {
            continue;
        }
        const perCell = row.querySelector('td.per');
        if (perCell) {
            const holding = holdingByTicker.get(ticker);
            const currentPrice = holding ? holding.currentPrice : null;
            perCell.textContent = formatPerDisplayForTicker(
                ticker,
                marketRatiosByTicker,
                currentPrice
            );
        }
    }
}

export async function loadAndDisplayPortfolioData(currentCurrency, exchangeRates, currencySymbols) {
    try {
        const { holdingsDetails, prices, baselinePrices } = await fetchPortfolioData();

        if (!holdingsDetails || !prices) {
            logger.error(
                'Essential holding or price data missing, cannot update portfolio display.'
            );
            return;
        }
        if (!exchangeRates || !currencySymbols) {
            logger.error(
                'Exchange rates or currency symbols missing, cannot update portfolio display correctly.'
            );
            return;
        }

        // Intraday day-change is only meaningful while the market trades; on
        // weekends/holidays the live quote just restates the last close.
        const showIntraday =
            isTradingDay(getNyDate()) && baselinePrices && typeof baselinePrices === 'object'
                ? baselinePrices
                : null;

        const {
            sortedHoldings,
            totalPortfolioValue: totalPortfolioValueUSD,
            totalPnl: totalPnlUSD,
            totalDayChange: totalDayChangeUSD,
        } = processAndEnrichHoldings(holdingsDetails, prices, showIntraday);
        const tickerSymbols = sortedHoldings.map((holding) => holding.ticker);
        const chartData = updateTableAndPrepareChartData(
            sortedHoldings,
            totalPortfolioValueUSD,
            currentCurrency,
            exchangeRates,
            currencySymbols,
            lastMarketRatiosByTicker ?? new Map()
        );

        document.getElementById('total-portfolio-value-in-table').textContent = formatCurrency(
            totalPortfolioValueUSD,
            currentCurrency,
            exchangeRates,
            currencySymbols
        );

        _renderPnlSummary(
            totalPnlUSD,
            totalPortfolioValueUSD,
            currentCurrency,
            exchangeRates,
            currencySymbols,
            totalDayChangeUSD
        );

        updatePieChart(chartData);
        checkAndToggleVerticalScroll();

        const marketRatiosByTicker = await fetchMarketRatiosForTickers(tickerSymbols);
        lastMarketRatiosByTicker = marketRatiosByTicker;
        _updatePerColumn(marketRatiosByTicker, sortedHoldings);
    } catch (error) {
        logger.error('Error fetching or processing fund data:', error);
    }
}

export async function getCalendarData(dataPaths) {
    const allData = await fetchData(dataPaths);
    const rates = allData.fx.rates;

    const historicalData = processHistoricalData(allData.historical);
    if (historicalData.length === 0) {
        throw new Error('No historical data available.');
    }

    const today = getNyDate();
    const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;

    const lastHistoricalData = historicalData[historicalData.length - 1];
    const baselineEntry =
        lastHistoricalData.date === todayStr && historicalData.length > 1
            ? historicalData[historicalData.length - 2]
            : lastHistoricalData;

    const realtimeData = calculateRealtimePnl(allData.holdings, allData.fund, baselineEntry, rates);

    const processedData = combineData(historicalData, realtimeData);
    const byDate = new Map(processedData.map((d) => [d.date, d]));
    const monthlyPnl = computeMonthlyPnl(processedData);

    return { processedData, byDate, rates, monthlyPnl };
}

import { niceNumber, getMonoFontFamily, colorWithAlpha, clamp01 } from './helpers.js';

function sanitizeRange(yMin, yMax) {
    const safeMin = Number.isFinite(yMin) ? Number(yMin) : 0;
    const safeMax = Number.isFinite(yMax) ? Number(yMax) : safeMin;
    let minValue = Math.min(safeMin, safeMax);
    let maxValue = Math.max(safeMin, safeMax);
    if (!Number.isFinite(minValue)) {
        minValue = 0;
    }
    if (!Number.isFinite(maxValue) || maxValue - minValue < 1e-6) {
        maxValue = minValue + 1;
    }
    return { minValue, maxValue, range: maxValue - minValue };
}

function calculatePercentSpacing(range, targetSegments) {
    const niceRange = niceNumber(range, false);
    let tickSpacing = Math.abs(niceNumber(niceRange / targetSegments, true));

    if (!Number.isFinite(tickSpacing) || tickSpacing === 0) {
        tickSpacing = Math.abs(niceNumber(range / targetSegments, true));
    }
    if (!Number.isFinite(tickSpacing) || tickSpacing === 0) {
        tickSpacing = range / targetSegments;
    }
    return Math.max(tickSpacing, 1e-2);
}

function generatePercentTicksForSpacing(minValue, maxValue, tickSpacing) {
    const startTick = Math.floor(minValue / tickSpacing) * tickSpacing;
    const endTick = Math.ceil(maxValue / tickSpacing) * tickSpacing;
    const ticks = [];
    for (let tick = startTick; tick <= endTick + tickSpacing * 0.001; tick += tickSpacing) {
        const rounded = Number((Math.round(tick / tickSpacing) * tickSpacing).toFixed(6));
        ticks.push(rounded);
    }
    return { ticks, startTick, endTick };
}

export function computePercentTickInfo(yMin, yMax) {
    const { minValue, maxValue, range } = sanitizeRange(yMin, yMax);
    const desiredTicks = 6;
    const targetSegments = Math.max(1, desiredTicks - 1);
    let tickSpacing = calculatePercentSpacing(range, targetSegments);

    const minRequiredTicks = 5;
    const maxRetries = 6;
    let result = { ticks: [], startTick: 0, endTick: 0 };

    for (let retry = 0; retry < maxRetries; retry++) {
        result = generatePercentTicksForSpacing(minValue, maxValue, tickSpacing);
        const viewTicks = result.ticks.filter(
            (t) => t >= minValue - tickSpacing * 0.25 && t <= maxValue + tickSpacing * 0.25
        );

        if (viewTicks.length >= minRequiredTicks) {
            break;
        }

        tickSpacing /= 2;
        if (tickSpacing < 1e-2) {
            break;
        }
    }

    return {
        ticks: result.ticks,
        tickSpacing,
        startTick: result.startTick,
        endTick: result.endTick,
    };
}

function handleFlatLineRange(yMin, yMax, range) {
    if (Number.isFinite(range) && range > 1e-9) {
        return { yMin, yMax, range };
    }
    const base = Math.abs(yMin) < 1e-9 ? 100 : Math.abs(yMin);
    const margin = base * 0.05; // +/- 5% margin
    const safeMargin = margin < 1e-9 ? 1 : margin;

    // Create artificial range
    const newMin = yMin - safeMargin;
    const newMax = yMax + safeMargin;
    return { yMin: newMin, yMax: newMax, range: newMax - newMin };
}

function calculateTickSpacing(yMin, yMax, maxTicks) {
    const initialRange = yMax - yMin;
    const {
        yMin: adjustedMin,
        yMax: adjustedMax,
        range,
    } = handleFlatLineRange(yMin, yMax, initialRange);

    const desiredTicks = maxTicks || 6;
    const targetSegments = Math.max(1, desiredTicks - 1) * (maxTicks ? 2 : 1);

    let tickSpacing = Math.abs(niceNumber(range / targetSegments, true));
    if (!Number.isFinite(tickSpacing) || tickSpacing === 0) {
        tickSpacing = Math.pow(10, Math.floor(Math.log10(Math.abs(range))));
    }
    // Duplicate check from original code
    if (!Number.isFinite(tickSpacing) || tickSpacing === 0) {
        tickSpacing = Math.pow(10, Math.floor(Math.log10(Math.abs(range))));
    }
    tickSpacing = Math.max(tickSpacing, 1e-6); // Avoid zero spacing

    return { yMin: adjustedMin, yMax: adjustedMax, tickSpacing };
}

function generateTickSequence(yMin, yMax, initialTickSpacing, maxTicks) {
    let finalTicks = [];
    const minRequiredTicks = maxTicks ? Math.floor(maxTicks * 0.5) : 5;
    const maxRetries = 6;
    let tickSpacing = initialTickSpacing;

    for (let retry = 0; retry < maxRetries; retry++) {
        // Do not clamp to zero if we have negative values (e.g. drawdown or PnL)
        const clampToZero = yMin >= 0;
        const niceMin = clampToZero
            ? Math.max(0, Math.floor(yMin / tickSpacing) * tickSpacing)
            : Math.floor(yMin / tickSpacing) * tickSpacing;
        const niceMax = Math.ceil(yMax / tickSpacing) * tickSpacing;

        // Safety break if tickSpacing became dangerously small
        if (tickSpacing <= 1e-9) {
            break;
        }

        const ticks = [];
        // Add a small buffer to loop limit to avoid floating point issues excluding the last tick
        for (let tick = niceMin; tick <= niceMax + tickSpacing * 0.001; tick += tickSpacing) {
            // Precision rounding to avoid 0.30000000004
            const rounded = Number((Math.round(tick / tickSpacing) * tickSpacing).toFixed(6));
            ticks.push(rounded);
        }

        // Filter to view range with slight buffer
        const viewTicks = ticks.filter(
            (tick) => tick >= yMin - tickSpacing * 0.25 && tick <= yMax + tickSpacing * 0.25
        );

        if (viewTicks.length >= minRequiredTicks) {
            finalTicks = viewTicks;
            break;
        }

        // If we didn't get enough ticks, halve the spacing and try again
        tickSpacing /= 2;

        // If this was the last retry and we still don't have enough, just use what we have (best effort)
        if (retry === maxRetries - 1) {
            finalTicks = viewTicks;
        }
    }
    return finalTicks;
}

export function generateConcreteTicks(yMin, yMax, isPerformanceChart, currency, options = {}) {
    if (isPerformanceChart) {
        const percentTickInfo = computePercentTickInfo(yMin, yMax);
        const margin = percentTickInfo.tickSpacing * 0.25;
        return percentTickInfo.ticks.filter(
            (tick) => tick >= yMin - margin && tick <= yMax + margin
        );
    }

    // maxTicks: compact panes (e.g. the volume subpane) ask for fewer, larger
    // steps instead of the default dense grid
    const maxTicks = Number.isFinite(options?.maxTicks) ? Math.max(1, options.maxTicks) : null;
    const {
        yMin: adjustedMin,
        yMax: adjustedMax,
        tickSpacing,
    } = calculateTickSpacing(yMin, yMax, maxTicks);

    return generateTickSequence(adjustedMin, adjustedMax, tickSpacing, maxTicks);
}

function getPrimaryYearForSingleYear(startDate, endDate) {
    if (startDate.getFullYear() === endDate.getFullYear()) {
        return startDate.getFullYear();
    }
    const endOfStartYear = new Date(startDate.getFullYear(), 11, 31);
    const startOfEndYear = new Date(endDate.getFullYear(), 0, 1);
    const timeInStartYear = endOfStartYear.getTime() - startDate.getTime();
    const timeInEndYear = endDate.getTime() - startOfEndYear.getTime();
    return timeInEndYear > timeInStartYear ? endDate.getFullYear() : startDate.getFullYear();
}

function generateSingleYearTicks(startDate, endDate, minTime, maxTime, formatYear) {
    const ticks = [];
    const year = getPrimaryYearForSingleYear(startDate, endDate);
    const formattedYear = formatYear(year);
    const quarters = [
        { month: 0, label: `${formattedYear}`, isYearStart: true },
        { month: 3, label: 'Apr', isYearStart: false },
        { month: 6, label: 'Jul', isYearStart: false },
        { month: 9, label: 'Oct', isYearStart: false },
    ];

    const marginMs = 30 * 24 * 60 * 60 * 1000;
    for (let i = 0; i < quarters.length; i++) {
        const q = quarters[i];
        const quarterDate = new Date(year, q.month, 1).getTime();
        if (quarterDate >= minTime - marginMs && quarterDate <= maxTime + marginMs) {
            ticks.push({
                time: quarterDate,
                label: q.label,
                isYearStart: q.isYearStart,
            });
        }
    }

    if (startDate.getFullYear() !== endDate.getFullYear() && year === startDate.getFullYear()) {
        const newYearJan1 = new Date(endDate.getFullYear(), 0, 1).getTime();
        if (newYearJan1 >= minTime && newYearJan1 <= maxTime) {
            ticks.push({
                time: newYearJan1,
                label: `${formatYear(endDate.getFullYear())}`,
                isYearStart: true,
            });
        }
    }
    return ticks;
}

function generateMultiYearTicks(startDate, endDate, minTime, maxTime, formatYear) {
    const ticks = [];
    for (let year = startDate.getFullYear(); year <= endDate.getFullYear(); year++) {
        const jan1 = new Date(year, 0, 1).getTime();
        if (jan1 >= minTime && jan1 <= maxTime) {
            ticks.push({
                time: jan1,
                label: `${formatYear(year)}`,
                isYearStart: true,
            });
        }
    }
    return ticks;
}

function createEndTick(endDate, maxTime, ticks, formatYear) {
    const endMonth = endDate.toLocaleDateString('en-US', { month: 'short' });
    const endYear = endDate.getFullYear();
    const hasYearTick = ticks.some(
        (t) => t.isYearStart && new Date(t.time).getFullYear() === endYear
    );

    let endLabel;
    if (endMonth === 'Jan' && hasYearTick) {
        endLabel = 'Jan';
    } else {
        endLabel = endMonth === 'Jan' ? `${formatYear(endYear)}` : endMonth;
    }

    return {
        time: maxTime,
        label: endLabel,
        isYearStart: endMonth === 'Jan' && !hasYearTick,
    };
}

function createStartTick(startDate, endDate, minTime, isSingleYear, isMobile, formatYear) {
    const startMonth = startDate.toLocaleDateString('en-US', { month: 'short' });
    const startYear = startDate.getFullYear();

    if (isSingleYear) {
        const displayYear =
            startDate.getFullYear() === endDate.getFullYear()
                ? startDate.getFullYear()
                : startDate.getMonth() >= 6
                  ? endDate.getFullYear()
                  : startDate.getFullYear();
        return {
            time: minTime,
            label: `${formatYear(displayYear)}`,
            isYearStart: true,
        };
    }

    if (!isMobile) {
        return {
            time: minTime,
            label: startMonth === 'Jan' ? `${formatYear(startYear)}` : startMonth,
            isYearStart: startMonth === 'Jan',
        };
    }

    return null;
}

export function generateYearBasedTicks(minTime, maxTime) {
    const startDate = new Date(minTime);
    const endDate = new Date(maxTime);
    const isMobile = typeof window !== 'undefined' ? window.innerWidth <= 768 : false;
    const formatYear = (year) => (isMobile ? `'${String(year).slice(2)}` : year);

    const dataSpanMonths =
        (endDate.getFullYear() - startDate.getFullYear()) * 12 +
        (endDate.getMonth() - startDate.getMonth()) +
        1;
    const isSingleYear = startDate.getFullYear() === endDate.getFullYear() || dataSpanMonths <= 15;

    const ticks = isSingleYear
        ? generateSingleYearTicks(startDate, endDate, minTime, maxTime, formatYear)
        : generateMultiYearTicks(startDate, endDate, minTime, maxTime, formatYear);

    ticks.push(createEndTick(endDate, maxTime, ticks, formatYear));

    const startTick = createStartTick(
        startDate,
        endDate,
        minTime,
        isSingleYear,
        isMobile,
        formatYear
    );
    if (startTick && !ticks.some((tick) => tick.time === minTime)) {
        ticks.push(startTick);
    }

    ticks.sort((a, b) => a.time - b.time);
    return ticks;
}

function preparePrioritizedTicks(ticks, yScale, yMin, yMax) {
    let ticksMax = -Infinity;
    let ticksMin = Infinity;
    for (let i = 0; i < ticks.length; i++) {
        const v = ticks[i];
        if (v > ticksMax) {
            ticksMax = v;
        }
        if (v < ticksMin) {
            ticksMin = v;
        }
    }

    const filteredTicks = new Array(ticks.length);
    for (let i = 0; i < ticks.length; i++) {
        const value = ticks[i];
        let priority = 2;
        const absVal = Math.abs(value);
        if (absVal < 1e-9) {
            priority = 0;
        } else if (value === yMax || value === yMin || value === ticksMax || value === ticksMin) {
            priority = 1;
        }
        filteredTicks[i] = { value, y: yScale(value), priority, abs: absVal };
    }

    filteredTicks.sort((a, b) => b.abs - a.abs);
    return filteredTicks;
}

function checkTickCollision(tickY, selectedTicks, minSpacingPixels, avoidY, minAvoidSpacing) {
    for (let s = 0; s < selectedTicks.length; s++) {
        if (Math.abs(tickY - selectedTicks[s].y) < minSpacingPixels) {
            return true;
        }
    }
    if (Array.isArray(avoidY) && avoidY.length > 0) {
        for (let a = 0; a < avoidY.length; a++) {
            if (Math.abs(tickY - avoidY[a]) < minAvoidSpacing) {
                return true;
            }
        }
    }
    return false;
}

function selectYAxisTicks(ticks, yScale, fontSize, isMobile, yMin, yMax, avoidY) {
    const minSpacingPixels = Math.floor(fontSize);
    const minAvoidSpacing = fontSize + (isMobile ? 4 : 6);
    const prioritizedTicks = preparePrioritizedTicks(ticks, yScale, yMin, yMax);
    const selectedTicks = [];

    for (let p = 0; p <= 2; p++) {
        for (let i = 0; i < prioritizedTicks.length; i++) {
            const tick = prioritizedTicks[i];
            if (tick.priority !== p) {
                continue;
            }

            if (
                !checkTickCollision(
                    tick.y,
                    selectedTicks,
                    minSpacingPixels,
                    avoidY,
                    minAvoidSpacing
                )
            ) {
                selectedTicks.push(tick);
            }
        }
    }
    return selectedTicks;
}

function renderYAxis(
    ctx,
    selectedTicks,
    padding,
    plotWidth,
    fontSize,
    monoFont,
    isMobile,
    yLabelFormatter
) {
    const halfTextHeight = fontSize / 2;
    for (let i = 0; i < selectedTicks.length; i++) {
        const { value, y } = selectedTicks[i];
        ctx.beginPath();
        ctx.moveTo(padding.left, y);
        ctx.lineTo(padding.left + plotWidth, y);
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
        ctx.stroke();
        ctx.fillStyle = '#8b949e';
        ctx.font = `${fontSize}px ${monoFont}`;
        ctx.textAlign = 'right';
        ctx.textBaseline = y - halfTextHeight < 2 ? 'top' : 'middle';
        ctx.fillText(yLabelFormatter(value), padding.left - (isMobile ? 8 : 10), y);
    }
}

function renderXAxisGrid(ctx, tick, x, padding, plotHeight, plotWidth) {
    if (x <= padding.left + 5 || x >= padding.left + plotWidth - 5) {
        return;
    }
    if (tick.isYearStart) {
        ctx.beginPath();
        ctx.setLineDash([3, 3]);
        ctx.moveTo(x, padding.top);
        ctx.lineTo(x, padding.top + plotHeight);
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
        ctx.stroke();
        ctx.setLineDash([]);
    } else if (
        tick.label.includes('Apr') ||
        tick.label.includes('Jul') ||
        tick.label.includes('Oct')
    ) {
        ctx.beginPath();
        ctx.setLineDash([2, 2]);
        ctx.moveTo(x, padding.top);
        ctx.lineTo(x, padding.top + plotHeight);
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
        ctx.stroke();
        ctx.setLineDash([]);
    }
}

function renderXAxis(
    ctx,
    yearTicks,
    xScale,
    padding,
    plotWidth,
    plotHeight,
    isMobile,
    monoFont,
    drawXAxis
) {
    if (drawXAxis) {
        ctx.beginPath();
        ctx.moveTo(padding.left, padding.top + plotHeight);
        ctx.lineTo(padding.left + plotWidth, padding.top + plotHeight);
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
        ctx.lineWidth = 1.5;
        ctx.stroke();
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.font = isMobile ? `9px ${monoFont}` : `11px ${monoFont}`;
    }

    const minSpacing = isMobile ? 30 : 40;
    for (let index = 0; index < yearTicks.length; index++) {
        const tick = yearTicks[index];
        const x = xScale(tick.time);

        let shouldDrawLabel = true;
        if (index > 0) {
            const prevTickX = xScale(yearTicks[index - 1].time);
            if (x - prevTickX < minSpacing) {
                shouldDrawLabel = false;
            }
        }

        if (drawXAxis && shouldDrawLabel) {
            if (isMobile && index === yearTicks.length - 1) {
                ctx.textAlign = 'right';
            } else {
                ctx.textAlign = 'center';
            }

            ctx.beginPath();
            ctx.moveTo(x, padding.top + plotHeight);
            ctx.lineTo(x, padding.top + plotHeight + (isMobile ? 4 : 6));
            ctx.stroke();

            ctx.fillText(tick.label, x, padding.top + plotHeight + (isMobile ? 8 : 10));
        }

        renderXAxisGrid(ctx, tick, x, padding, plotHeight, plotWidth);
    }
}

export function drawAxes(
    ctx,
    padding,
    plotWidth,
    plotHeight,
    minTime,
    maxTime,
    yMin,
    yMax,
    xScale,
    yScale,
    yLabelFormatter,
    isPerformanceChart = false,
    axisOptions = {},
    currency = 'USD',
    forcePercent = false
) {
    const isMobile = typeof window !== 'undefined' ? window.innerWidth <= 768 : false;
    const monoFont = getMonoFontFamily();
    const { drawXAxis = true, drawYAxis = true, maxTicks = null, avoidY = [] } = axisOptions;

    const ticks = generateConcreteTicks(yMin, yMax, isPerformanceChart || forcePercent, currency, {
        maxTicks,
    });

    let selectedTicks = [];
    if (drawYAxis) {
        const fontSize = isMobile ? 9 : 11;
        selectedTicks = selectYAxisTicks(ticks, yScale, fontSize, isMobile, yMin, yMax, avoidY);
        renderYAxis(
            ctx,
            selectedTicks,
            padding,
            plotWidth,
            fontSize,
            monoFont,
            isMobile,
            yLabelFormatter
        );
    }

    const yearTicks = generateYearBasedTicks(minTime, maxTime);
    renderXAxis(
        ctx,
        yearTicks,
        xScale,
        padding,
        plotWidth,
        plotHeight,
        isMobile,
        monoFont,
        drawXAxis
    );

    return { selectedTicks };
}

function getSharedCanvas(width, height) {
    if (!drawMountainFill._sharedCanvas && typeof document !== 'undefined') {
        drawMountainFill._sharedCanvas = document.createElement('canvas');
        drawMountainFill._sharedCtx = drawMountainFill._sharedCanvas.getContext('2d');
    }

    const offscreen = drawMountainFill._sharedCanvas;
    const offCtx = drawMountainFill._sharedCtx;

    if (!offscreen || !offCtx) {
        return null;
    }

    if (offscreen.width !== width) {
        offscreen.width = width;
    }
    if (offscreen.height !== height) {
        offscreen.height = height;
    }
    offCtx.clearRect(0, 0, width, height);
    return { offscreen, offCtx };
}

function applyMountainFillColor(offCtx, width, color, colorStops) {
    if (Array.isArray(colorStops) && colorStops.length > 0) {
        const horizontalGradient = offCtx.createLinearGradient(0, 0, width, 0);
        const stopCount = colorStops.length;
        for (let index = 0; index < stopCount; index++) {
            const stopColor = colorStops[index];
            const offset = stopCount === 1 ? 0 : index / (stopCount - 1);
            horizontalGradient.addColorStop(offset, colorWithAlpha(stopColor, 1));
        }
        offCtx.fillStyle = horizontalGradient;
    } else {
        offCtx.fillStyle = colorWithAlpha(color, 1);
    }
    offCtx.fill();
}

function applyMountainFillAlphaGradient(
    offCtx,
    width,
    height,
    areaCoords,
    clampedBaselineY,
    bounds,
    opacityTop,
    opacityBottom
) {
    let minYRel = clampedBaselineY - bounds.top;
    let maxYRel = clampedBaselineY - bounds.top;
    for (let i = 0; i < areaCoords.length; i += 1) {
        const relativeY = areaCoords[i].y - bounds.top;
        if (relativeY < minYRel) {
            minYRel = relativeY;
        }
        if (relativeY > maxYRel) {
            maxYRel = relativeY;
        }
    }
    const gradientTop = Math.min(minYRel, maxYRel - 0.0001);
    const gradientBottom = Math.max(maxYRel, gradientTop + 0.0001);

    offCtx.globalCompositeOperation = 'destination-in';
    const alphaGradient = offCtx.createLinearGradient(0, gradientTop, 0, gradientBottom);
    alphaGradient.addColorStop(0, `rgba(0, 0, 0, ${clamp01(opacityTop)})`);
    alphaGradient.addColorStop(1, `rgba(0, 0, 0, ${clamp01(opacityBottom)})`);
    offCtx.fillStyle = alphaGradient;
    offCtx.fillRect(0, 0, width, height);
    offCtx.globalCompositeOperation = 'source-over';
}

export function drawMountainFill(ctx, coords, baselineY, options) {
    if (!Array.isArray(coords) || coords.length === 0) {
        return;
    }

    const { color, colorStops, opacityTop = 0.35, opacityBottom = 0, bounds } = options || {};

    if (!bounds || bounds.right <= bounds.left || bounds.bottom <= bounds.top) {
        return;
    }

    if (typeof document === 'undefined' || !Number.isFinite(baselineY)) {
        return;
    }

    const clampedBaselineY = Math.min(Math.max(baselineY, bounds.top), bounds.bottom);
    const baseCoords = coords.length === 1 ? [coords[0], coords[0]] : coords;
    const areaCoords = new Array(baseCoords.length);
    for (let i = 0; i < baseCoords.length; i++) {
        areaCoords[i] = {
            x: baseCoords[i].x,
            y: baseCoords[i].y,
        };
    }

    const width = Math.max(1, Math.ceil(bounds.right - bounds.left));
    const height = Math.max(1, Math.ceil(bounds.bottom - bounds.top));

    const shared = getSharedCanvas(width, height);
    if (!shared) {
        return;
    }
    const { offscreen, offCtx } = shared;

    offCtx.beginPath();
    offCtx.moveTo(areaCoords[0].x - bounds.left, areaCoords[0].y - bounds.top);
    for (let i = 1; i < areaCoords.length; i += 1) {
        offCtx.lineTo(areaCoords[i].x - bounds.left, areaCoords[i].y - bounds.top);
    }
    offCtx.lineTo(areaCoords[areaCoords.length - 1].x - bounds.left, clampedBaselineY - bounds.top);
    offCtx.lineTo(areaCoords[0].x - bounds.left, clampedBaselineY - bounds.top);
    offCtx.closePath();

    applyMountainFillColor(offCtx, width, color, colorStops);
    applyMountainFillAlphaGradient(
        offCtx,
        width,
        height,
        areaCoords,
        clampedBaselineY,
        bounds,
        opacityTop,
        opacityBottom
    );

    ctx.drawImage(offscreen, bounds.left, bounds.top);
}

export function drawMarker(context, x, y, radius, isBuy, colors, chartBounds) {
    const clampedY = Math.max(chartBounds.top + radius, Math.min(y, chartBounds.bottom - radius));

    context.beginPath();
    context.arc(x, clampedY, radius, 0, Math.PI * 2);
    context.fillStyle = isBuy ? colors.buyFill : colors.sellFill;
    context.strokeStyle = isBuy ? colors.buy : colors.sell;
    context.lineWidth = 1;
    context.fill();
    context.stroke();
}

/**
 * Nudge a label's vertical position so it does not overlap any previously
 * placed labels.  The function tries moving the label in the direction that
 * keeps it closer to its natural position (where the data line is); if that
 * would push it out of the visible plot area it tries the other direction.
 *
 * @param {number} textY – initial y centre of the label
 * @param {number} textHeight – total text height
 * @param {number} bgPadding – padding around the text background
 * @param {Array} existingBounds – bounding boxes of previously placed labels
 * @param {object} padding – chart padding ({ top, … })
 * @param {number} plotHeight – available plot height
 * @param {number} [naturalY] – optional, the y position of the data point
 *   on the chart.  When provided, the nudge direction will prefer moving
 *   toward this position rather than always trying downward first.
 */
export function nudgeLabelPosition(
    textY,
    textHeight,
    bgPadding,
    existingBounds,
    padding,
    plotHeight,
    naturalY
) {
    if (!Number.isFinite(textY)) {
        return textY;
    }
    if (!Array.isArray(existingBounds) || existingBounds.length === 0) {
        return textY;
    }

    // Filter out invalid bounds
    const validBounds = existingBounds.filter(
        (b) => Number.isFinite(b.y) && Number.isFinite(b.height)
    );
    if (validBounds.length === 0) {
        return textY;
    }

    const targetY = naturalY !== undefined ? naturalY : textY;
    const halfHeight = textHeight / 2 + bgPadding;
    const minY = padding.top + halfHeight;
    const maxY = padding.top + plotHeight - halfHeight;
    const gap = 2;

    // 1. Generate candidates: target, plus just above/below each existing label
    const candidates = [targetY];
    for (const bound of validBounds) {
        const boundTop = bound.y - bound.height / 2;
        const boundBottom = bound.y + bound.height / 2;

        candidates.push(boundTop - gap - halfHeight);
        candidates.push(boundBottom + gap + halfHeight);
    }

    // 2. Sort candidates by distance to targetY to find best position
    candidates.sort((a, b) => Math.abs(a - targetY) - Math.abs(b - targetY));

    // 3. Find first valid candidate that doesn't overlap
    for (const candidateY of candidates) {
        // Clamp to plot area first
        const y = Math.max(minY, Math.min(candidateY, maxY));

        // Check if this position causes overlap
        const myTop = y - halfHeight;
        const myBottom = y + halfHeight;
        let overlap = false;

        for (const bound of validBounds) {
            const bTop = bound.y - bound.height / 2;
            const bBottom = bound.y + bound.height / 2;

            // Simple vertical overlap check (assuming shared X space)
            if (myBottom > bTop && myTop < bBottom) {
                overlap = true;
                break;
            }
        }

        if (!overlap) {
            return y;
        }
    }

    // Fallback: if all candidate positions overlap (e.g. crowded),
    // return the target position clamped to screen
    return Math.max(minY, Math.min(targetY, maxY));
}

function calculateEndValuePosition(
    x,
    y,
    textWidth,
    textHeight,
    isMobile,
    padding,
    plotWidth,
    plotHeight
) {
    if (isMobile) {
        return {
            textX: padding.left + plotWidth - textWidth - 5,
            textY: Math.max(
                padding.top + textHeight / 2,
                Math.min(y, padding.top + plotHeight - textHeight / 2)
            ),
        };
    }

    const spaceAbove = y - padding.top;
    const spaceBelow = padding.top + plotHeight - y;
    let textX;
    let textY;

    if (spaceAbove > textHeight + 8) {
        textX = x + 3;
        textY = y - 3;
    } else if (spaceBelow > textHeight + 8) {
        textX = x + 3;
        textY = y + textHeight + 3;
    } else {
        textX = padding.left + plotWidth - textWidth - 5;
        textY = Math.max(
            padding.top + textHeight / 2,
            Math.min(y, padding.top + plotHeight - textHeight / 2)
        );
    }

    if (textX + textWidth > padding.left + plotWidth - 5) {
        textX = padding.left + plotWidth - textWidth - 5;
    }

    return { textX, textY };
}

export function drawEndValue(
    context,
    x,
    y,
    value,
    color,
    isMobile,
    padding,
    plotWidth,
    plotHeight,
    formatValue,
    showBackground = false,
    existingBounds = null
) {
    const text = formatValue(value);
    const fontSize = isMobile ? 9 : 11;
    const fontFamily = getMonoFontFamily();

    context.font = `${fontSize}px ${fontFamily}`;
    context.textAlign = 'left';
    context.textBaseline = 'middle';

    const textMetrics = context.measureText(text);
    const textWidth = textMetrics.width;
    const textHeight = fontSize;
    const bgPadding = 4;

    const rawPos = calculateEndValuePosition(
        x,
        y,
        textWidth,
        textHeight,
        isMobile,
        padding,
        plotWidth,
        plotHeight
    );

    const textX = Math.max(
        padding.left + 2,
        Math.min(rawPos.textX, padding.left + plotWidth - textWidth - 2)
    );
    let textY = Math.max(
        padding.top + textHeight / 2,
        Math.min(rawPos.textY, padding.top + plotHeight - textHeight / 2)
    );

    // Nudge away from any previously drawn labels
    if (existingBounds) {
        textY = nudgeLabelPosition(
            textY,
            textHeight,
            bgPadding,
            existingBounds,
            padding,
            plotHeight,
            y
        );
    }

    if (showBackground) {
        context.fillStyle = 'rgba(0, 0, 0, 0.4)';
        context.beginPath();
        if (typeof context.roundRect === 'function') {
            context.roundRect(
                textX - bgPadding,
                textY - textHeight / 2 - bgPadding,
                textWidth + bgPadding * 2,
                textHeight + bgPadding * 2,
                3
            );
        } else {
            context.rect(
                textX - bgPadding,
                textY - textHeight / 2 - bgPadding,
                textWidth + bgPadding * 2,
                textHeight + bgPadding * 2
            );
        }
        context.fill();
    }

    context.fillStyle = color;
    context.fillText(text, textX, textY);

    return {
        x: textX,
        y: textY,
        width: textWidth + bgPadding * 2,
        height: textHeight + bgPadding * 2,
    };
}

export function drawStartValue(
    context,
    x,
    y,
    value,
    color,
    isMobile,
    padding,
    plotWidth,
    plotHeight,
    formatValue,
    showBackground = false,
    existingBounds = null
) {
    const text = formatValue(value);
    const fontSize = isMobile ? 9 : 11;
    const fontFamily = getMonoFontFamily();

    context.font = `${fontSize}px ${fontFamily}`;
    context.textAlign = 'left';
    context.textBaseline = 'middle';

    const textMetrics = context.measureText(text);
    const textWidth = textMetrics.width;
    const textHeight = fontSize;
    const bgPadding = 4;

    // Anchor near the left plot boundary while respecting vertical limits
    const baseX = padding.left + (isMobile ? 4 : 6);
    const textX = Math.min(baseX, padding.left + plotWidth - textWidth - 2);
    let textY = Math.max(
        padding.top + textHeight / 2,
        Math.min(y, padding.top + plotHeight - textHeight / 2)
    );

    // Nudge away from any previously drawn labels
    if (existingBounds) {
        textY = nudgeLabelPosition(
            textY,
            textHeight,
            bgPadding,
            existingBounds,
            padding,
            plotHeight,
            y
        );
    }

    if (showBackground) {
        context.fillStyle = 'rgba(0, 0, 0, 0.4)';
        context.beginPath();
        if (typeof context.roundRect === 'function') {
            context.roundRect(
                textX - bgPadding,
                textY - textHeight / 2 - bgPadding,
                textWidth + bgPadding * 2,
                textHeight + bgPadding * 2,
                3
            );
        } else {
            context.rect(
                textX - bgPadding,
                textY - textHeight / 2 - bgPadding,
                textWidth + bgPadding * 2,
                textHeight + bgPadding * 2
            );
        }
        context.fill();
    }

    context.fillStyle = color;
    context.fillText(text, textX, textY);

    return {
        x: textX,
        y: textY,
        width: textWidth + bgPadding * 2,
        height: textHeight + bgPadding * 2,
    };
}

import { transactionState } from '../../state.js';
import { convertValueToCurrency } from '../../utils.js';
import { getSplitAdjustment } from '../../calculations.js';
import { parseLocalDate, createTimeInterpolator } from '../helpers.js';

const contributionSeriesCache = new WeakMap();
const filteredBalanceSeriesCache = new WeakMap();

// Format a Date as YYYY-MM-DD using LOCAL calendar components. Never use
// toISOString() for day keys derived from local-midnight dates: in UTC+
// timezones it lands on the previous calendar day, which misaligns the
// balance series against the contribution series (appreciation then spikes
// by the buy amount at every transaction).
function toLocalISODate(date) {
    return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

export function getContributionSeriesForTransactions(
    transactions,
    { includeSyntheticStart = false, padToDate = null, currency = null } = {}
) {
    if (!Array.isArray(transactions) || transactions.length === 0) {
        return [];
    }
    const splitHistoryRef = transactionState.splitHistory;
    const cached = contributionSeriesCache.get(transactions);
    const targetCurrency = currency || transactionState.selectedCurrency || 'USD';
    if (
        cached &&
        cached.splitHistory === splitHistoryRef &&
        cached.includeSyntheticStart === includeSyntheticStart &&
        cached.padToDate === padToDate &&
        cached.currency === targetCurrency
    ) {
        return cached.series;
    }
    const series = buildContributionSeriesFromTransactions(transactions, {
        includeSyntheticStart,
        padToDate,
        currency: targetCurrency,
    });
    contributionSeriesCache.set(transactions, {
        splitHistory: splitHistoryRef,
        includeSyntheticStart,
        padToDate,
        currency: targetCurrency,
        series,
    });
    return series;
}

export function buildContributionSeriesFromTransactions(
    transactions,
    { includeSyntheticStart = false, padToDate = null, currency = null } = {}
) {
    if (!Array.isArray(transactions) || transactions.length === 0) {
        return [];
    }

    const normalizedTransactions = transactions.map((t) => {
        const d = parseLocalDate(t.tradeDate);
        const isoDate = d ? toLocalISODate(d) : (t.tradeDate || '').trim();
        return { ...t, tradeDate: isoDate };
    });

    const sortedTransactions = normalizedTransactions.sort(
        (a, b) =>
            (a.tradeDate < b.tradeDate ? -1 : a.tradeDate > b.tradeDate ? 1 : 0) ||
            (a.transactionId ?? 0) - (b.transactionId ?? 0)
    );

    // Consolidate transactions by date
    const dailyMap = new Map();
    for (let i = 0; i < sortedTransactions.length; i++) {
        const t = sortedTransactions[i];
        const dateStr = t.tradeDate;
        if (!dailyMap.has(dateStr)) {
            dailyMap.set(dateStr, {
                netAmount: 0,
                orderTypes: new Set(),
                buyVolume: 0,
                sellVolume: 0,
            });
        }
        const entry = dailyMap.get(dateStr);
        const amount = Number.parseFloat(t.netAmount) || 0;
        entry.netAmount += amount;
        entry.orderTypes.add(t.orderType);

        const type = String(t.orderType).toLowerCase();
        if (type === 'buy') {
            entry.buyVolume += Math.abs(amount);
        } else if (type === 'sell') {
            entry.sellVolume += Math.abs(amount);
        }
    }

    // Bolt: Replaced Array.from(dailyMap.keys()).sort() with explicit pre-allocated array and manual iteration to reduce GC overhead
    const uniqueDates = new Array(dailyMap.size);
    let dateIdx = 0;
    for (const dateStr of dailyMap.keys()) {
        uniqueDates[dateIdx++] = dateStr;
    }
    uniqueDates.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));

    const series = [];
    let cumulativeAmount = 0;

    for (let index = 0; index < uniqueDates.length; index++) {
        const dateStr = uniqueDates[index];
        const entry = dailyMap.get(dateStr);
        const netDelta = entry.netAmount;

        if (index > 0) {
            // UTC-domain: uniqueDates are normalized YYYY-MM-DD strings, so
            // new Date() parses them as UTC midnight and toISOString() round-trips.
            const prevDateStr = uniqueDates[index - 1];
            const prevDate = new Date(prevDateStr);
            const currentDate = new Date(dateStr);

            // eslint-disable-next-line no-restricted-syntax -- UTC-domain (see above)
            if (prevDate.toISOString().split('T')[0] !== currentDate.toISOString().split('T')[0]) {
                const intermediateDate = new Date(currentDate);
                intermediateDate.setDate(intermediateDate.getDate() - 1);

                // Only add padding if there is actually a gap > 1 day
                const prevPlusOne = new Date(prevDate);
                prevPlusOne.setDate(prevPlusOne.getDate() + 1);

                if (intermediateDate > prevDate) {
                    series.push({
                        // eslint-disable-next-line no-restricted-syntax -- UTC-domain (see above)
                        tradeDate: intermediateDate.toISOString().split('T')[0],
                        amount: cumulativeAmount,
                        value: cumulativeAmount,
                        orderType: 'padding',
                        netAmount: 0,
                    });
                }
            }
        }

        cumulativeAmount += netDelta;

        // Determine a representative order type for the consolidated point
        let orderType = 'mixed';
        if (entry.orderTypes.size === 1) {
            orderType = entry.orderTypes.values().next().value;
        } else if (entry.orderTypes.size > 0) {
            let allBuy = true;
            let allSell = true;
            for (const t of entry.orderTypes) {
                const lowerT = String(t).toLowerCase();
                if (lowerT !== 'buy') {allBuy = false;}
                if (lowerT !== 'sell') {allSell = false;}
                if (!allBuy && !allSell) {break;}
            }
            if (allBuy) {
                orderType = 'buy';
            } else if (allSell) {
                orderType = 'sell';
            }
        }

        series.push({
            tradeDate: dateStr,
            amount: cumulativeAmount,
            value: cumulativeAmount,
            orderType: orderType,
            netAmount: netDelta,
            buyVolume: entry.buyVolume,
            sellVolume: entry.sellVolume,
        });
    }

    const lastPoint = series[series.length - 1];
    if (lastPoint) {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const targetDateRaw = padToDate ? new Date(padToDate) : today;
        const targetDate = Number.isNaN(targetDateRaw.getTime()) ? today : targetDateRaw;
        targetDate.setHours(0, 0, 0, 0);
        const clampedTarget = targetDate > today ? today : targetDate;
        const lastTransactionDate = parseLocalDate(lastPoint.tradeDate);

        if (lastTransactionDate && clampedTarget > lastTransactionDate) {
            series.push({
                tradeDate: toLocalISODate(clampedTarget),
                amount: lastPoint.amount,
                value: lastPoint.amount,
                orderType: 'padding',
                netAmount: 0,
            });
        }
    }

    if (includeSyntheticStart && series.length > 0) {
        const epsilon = 1e-6;
        const firstActual =
            series.find((point) => (point.orderType || '').toLowerCase() !== 'padding') ||
            series[0];
        const firstValue = Number(firstActual?.amount) || 0;
        const firstDate = new Date(firstActual?.tradeDate || firstActual?.date);
        if (!Number.isNaN(firstDate.getTime()) && Math.abs(firstValue) > epsilon) {
            const syntheticDate = new Date(firstDate);
            syntheticDate.setDate(syntheticDate.getDate() - 1);
            // eslint-disable-next-line no-restricted-syntax -- UTC-domain: tradeDate is a normalized YYYY-MM-DD string, parsed as UTC midnight
            const syntheticDateStr = syntheticDate.toISOString().split('T')[0];
            const existing = series.find((point) => point.tradeDate === syntheticDateStr);
            if (!existing) {
                series.unshift({
                    tradeDate: syntheticDateStr,
                    amount: 0,
                    value: 0,
                    orderType: 'padding',
                    netAmount: 0,
                    synthetic: true,
                });
            }
        }
    }

    const selectedCurrency = currency || transactionState.selectedCurrency || 'USD';
    if (selectedCurrency === 'USD') {
        return series;
    }

    let cumulative = 0;
    return series.map((point) => {
        const dateRef = point.tradeDate || point.date;
        const convertedNet = convertValueToCurrency(point.netAmount, dateRef, selectedCurrency);
        cumulative += convertedNet;
        return {
            ...point,
            netAmount: convertedNet,
            amount: cumulative,
            value: cumulative,
            buyVolume: point.buyVolume
                ? convertValueToCurrency(point.buyVolume, dateRef, selectedCurrency)
                : point.buyVolume,
            sellVolume: point.sellVolume
                ? convertValueToCurrency(point.sellVolume, dateRef, selectedCurrency)
                : point.sellVolume,
        };
    });
}

function normalizeSymbolForPricing(symbol) {
    if (typeof symbol !== 'string') {
        return symbol;
    }
    return symbol.replace(/-/g, '').toUpperCase();
}

function getPriceFromHistoricalData(historicalPrices, symbol, dateStr) {
    if (!historicalPrices || typeof historicalPrices !== 'object') {
        return null;
    }
    const normalized = normalizeSymbolForPricing(symbol);
    const priceSeries =
        historicalPrices[normalized] ||
        historicalPrices[symbol] ||
        historicalPrices[symbol?.toUpperCase?.()] ||
        null;
    if (!priceSeries) {
        return null;
    }
    if (priceSeries[dateStr] !== undefined) {
        return priceSeries[dateStr];
    }
    const fallbackDate = new Date(dateStr);
    if (Number.isNaN(fallbackDate.getTime())) {
        return null;
    }
    for (let i = 0; i < 10; i += 1) {
        fallbackDate.setDate(fallbackDate.getDate() - 1);
        // eslint-disable-next-line no-restricted-syntax -- UTC-domain: dateStr is a YYYY-MM-DD string, parsed as UTC midnight
        const priorStr = fallbackDate.toISOString().split('T')[0];
        if (priceSeries[priorStr] !== undefined) {
            return priceSeries[priorStr];
        }
    }
    return null;
}

export function buildFilteredBalanceSeries(transactions, historicalPrices, splitHistory) {
    if (!Array.isArray(transactions) || transactions.length === 0) {
        return [];
    }

    // Identity-based cache: same (transactions, historicalPrices, splitHistory)
    // objects return the same computed series.
    if (historicalPrices && splitHistory) {
        const byPrices = filteredBalanceSeriesCache.get(transactions);
        if (byPrices) {
            const bySplits = byPrices.get(historicalPrices);
            if (bySplits) {
                const cached = bySplits.get(splitHistory);
                if (cached) {
                    return cached;
                }
            }
        }
    }

    const tsCache = new Map();
    const getTs = (t) => {
        let ts = tsCache.get(t);
        if (ts === undefined) {
            ts = parseLocalDate(t.tradeDate)?.getTime() ?? NaN;
            tsCache.set(t, ts);
        }
        return ts;
    };
    const sortedTransactions = [...transactions].sort(
        (a, b) => getTs(a) - getTs(b) || (a.transactionId ?? 0) - (b.transactionId ?? 0)
    );

    const firstDate = parseLocalDate(sortedTransactions[0].tradeDate);
    const lastTransactionDate = parseLocalDate(
        sortedTransactions[sortedTransactions.length - 1].tradeDate
    );
    if (!firstDate || !lastTransactionDate) {
        return [];
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const lastDate = today > lastTransactionDate ? today : lastTransactionDate;

    const splitsByDate = new Map();
    const splitArr = Array.isArray(splitHistory) ? splitHistory : [];
    for (let i = 0; i < splitArr.length; i++) {
        const split = splitArr[i];
        if (!split || !split.splitDate || !split.symbol) {
            continue;
        }
        const splitDate = parseLocalDate(split.splitDate);
        if (!splitDate) {
            continue;
        }
        const dateKey = toLocalISODate(splitDate);
        const multiplier = Number(split.splitMultiplier) || Number(split.split_multiplier) || 1;
        const symbolKey = normalizeSymbolForPricing(split.symbol);
        if (!splitsByDate.has(dateKey)) {
            splitsByDate.set(dateKey, []);
        }
        splitsByDate.get(dateKey).push({ symbol: symbolKey, multiplier });
    }

    const transactionsByDate = new Map();
    for (let i = 0; i < sortedTransactions.length; i++) {
        const txn = sortedTransactions[i];
        const txnDate = parseLocalDate(txn.tradeDate);
        if (!txnDate) {
            continue;
        }
        const dateStr = toLocalISODate(txnDate);
        if (!transactionsByDate.has(dateStr)) {
            transactionsByDate.set(dateStr, []);
        }
        transactionsByDate.get(dateStr).push(txn);
    }

    const holdings = new Map();
    const lastKnownPrices = new Map(); // Track last known price from transactions
    const series = [];
    const iterationStart = new Date(firstDate);
    iterationStart.setDate(iterationStart.getDate() - 1);

    const iterDate = new Date(iterationStart);

    while (iterDate <= lastDate) {
        const dateStr = toLocalISODate(iterDate);

        const splitsToday = splitsByDate.get(dateStr);
        if (splitsToday) {
            for (let i = 0; i < splitsToday.length; i++) {
                const { symbol, multiplier } = splitsToday[i];
                if (!Number.isFinite(multiplier) || multiplier <= 0) {
                    continue;
                }
                const currentQty = holdings.get(symbol);
                if (currentQty !== undefined) {
                    holdings.set(symbol, currentQty * multiplier);
                }
                // Adjust last known price for split
                const lastPrice = lastKnownPrices.get(symbol);
                if (lastPrice !== undefined && multiplier > 0) {
                    lastKnownPrices.set(symbol, lastPrice / multiplier);
                }
            }
        }

        const todaysTransactions = transactionsByDate.get(dateStr) || [];
        for (let i = 0; i < todaysTransactions.length; i++) {
            const txn = todaysTransactions[i];
            const normalizedSymbol = normalizeSymbolForPricing(txn.security);
            const quantity = parseFloat(txn.quantity) || 0;
            const txnPrice = parseFloat(txn.price);
            if (!Number.isFinite(quantity) || quantity === 0) {
                continue;
            }
            // Update last known price from this transaction
            if (Number.isFinite(txnPrice) && txnPrice > 0) {
                lastKnownPrices.set(normalizedSymbol, txnPrice);
            }
            const isBuy = String(txn.orderType).toLowerCase() === 'buy';
            const currentQty = holdings.get(normalizedSymbol) || 0;
            const updatedQty = currentQty + (isBuy ? quantity : -quantity);
            if (Math.abs(updatedQty) < 1e-8) {
                holdings.delete(normalizedSymbol);
            } else {
                holdings.set(normalizedSymbol, updatedQty);
            }
        }

        let totalValue = 0;
        for (const [symbol, qty] of holdings.entries()) {
            if (!Number.isFinite(qty) || Math.abs(qty) < 1e-8) {
                continue;
            }
            let price = getPriceFromHistoricalData(historicalPrices, symbol, dateStr);
            // Fallback to last known transaction price if historical price unavailable
            if (price === null) {
                price = lastKnownPrices.get(symbol) ?? null;
            }
            if (price === null) {
                continue;
            }
            const adjustment = getSplitAdjustment(splitHistory, symbol, dateStr);
            totalValue += qty * price * adjustment;
        }

        series.push({ date: dateStr, value: totalValue });
        iterDate.setDate(iterDate.getDate() + 1);
    }

    const epsilon = 1e-6;
    let keepSyntheticStart = false;
    for (let i = 0; i < series.length; i += 1) {
        const point = series[i];
        if (!point || !Number.isFinite(point.value)) {
            continue;
        }
        if (Math.abs(point.value) > epsilon) {
            if (i > 0 && Math.abs(series[i - 1]?.value || 0) <= epsilon) {
                keepSyntheticStart = true;
            }
            break;
        }
    }

    if (keepSyntheticStart && series.length > 0) {
        series[0].synthetic = true;
    } else if (series.length > 0 && Math.abs(series[0].value || 0) <= epsilon) {
        series.shift();
    }

    if (historicalPrices && splitHistory) {
        if (!filteredBalanceSeriesCache.has(transactions)) {
            filteredBalanceSeriesCache.set(transactions, new WeakMap());
        }
        const byPrices = filteredBalanceSeriesCache.get(transactions);
        if (!byPrices.has(historicalPrices)) {
            byPrices.set(historicalPrices, new WeakMap());
        }
        byPrices.get(historicalPrices).set(splitHistory, series);
    }

    return series;
}

export function applyDrawdownToSeries(data, valueKey, initialPeak = -Infinity) {
    if (!Array.isArray(data) || data.length === 0) {
        return [];
    }
    // Sort by date first
    const sorted = [...data].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
    let runningPeak = initialPeak;
    const len = sorted.length;
    // Bolt: Use pre-allocated Array and a standard loop instead of .map() to avoid closure allocations and eliminate array growth overhead.
    const result = new Array(len);
    for (let i = 0; i < len; i++) {
        const p = sorted[i];
        const val = p[valueKey];
        if (val > runningPeak) {
            runningPeak = val;
        }
        result[i] = {
            ...p,
            [valueKey]: val - runningPeak, // <= 0
        };
    }
    return result;
}

/**
 * Compute the appreciation series (balance − contribution) at aligned timestamps.
 * For each balance data point, the contribution value is matched exactly or
 * linearly interpolated from the contribution series.
 *
 * @param {Array<{date: Date, value: number}>} balanceData
 * @param {Array<{date: Date, amount: number}>} contributionData
 * @returns {Array<{date: Date, value: number}>}
 */
export function computeAppreciationSeries(balanceData, contributionData) {
    if (
        !Array.isArray(balanceData) ||
        balanceData.length === 0 ||
        !Array.isArray(contributionData) ||
        contributionData.length === 0
    ) {
        return [];
    }

    // Build exact-match map
    const contribByTime = new Map();
    for (let i = 0; i < contributionData.length; i++) {
        const item = contributionData[i];
        contribByTime.set(item.date.getTime(), item.amount);
    }

    // Sort contribution timestamps for interpolation
    const contribPoints = new Array(contributionData.length);
    for (let i = 0; i < contributionData.length; i++) {
        const item = contributionData[i];
        contribPoints[i] = { time: item.date.getTime(), value: item.amount };
    }
    const interpolateContrib = createTimeInterpolator(contribPoints);

    const result = [];
    for (let i = 0; i < balanceData.length; i++) {
        const balItem = balanceData[i];
        const t = balItem.date.getTime();
        let contribValue = contribByTime.get(t);
        if (contribValue === undefined) {
            contribValue = interpolateContrib(t);
        }
        if (
            contribValue !== null &&
            Number.isFinite(balItem.value) &&
            Number.isFinite(contribValue)
        ) {
            result.push({
                date: balItem.date,
                value: balItem.value - contribValue,
            });
        }
    }

    return result;
}

/**
 * Merge daily dividend data into a contribution series.
 * Dividends reduce the cumulative contribution (cash returned to investor).
 *
 * @param {Array} contributionSeries - from buildContributionSeriesFromTransactions
 * @param {Array|null} yieldData - from yield_data.json [{date, daily_dividend, ...}]
 * @param {string} currency - target currency
 * @param {Array|null} filterTickers - optional array of ticker symbols to filter by
 * @returns {Array} merged series with dividends subtracted
 */
export function mergeDividendsIntoContribution(
    contributionSeries,
    yieldData,
    currency,
    filterTickers = null
) {
    if (!Array.isArray(yieldData) || yieldData.length === 0) {
        return contributionSeries;
    }

    // Build a Map of dateStr → daily_dividend from yieldData (only non-zero entries)
    const dividendMap = new Map();
    for (let i = 0; i < yieldData.length; i++) {
        const item = yieldData[i];
        let dividend = 0;

        if (filterTickers && filterTickers.length > 0) {
            // If filtering is active, only include dividends for the filtered tickers
            if (item.daily_dividends_by_ticker) {
                for (let j = 0; j < filterTickers.length; j++) {
                    const ticker = filterTickers[j];
                    if (item.daily_dividends_by_ticker[ticker]) {
                        dividend += item.daily_dividends_by_ticker[ticker];
                    }
                }
            }
            // If item.daily_dividends_by_ticker is missing, dividend remains 0. We DO NOT fall back!
        } else if (item.daily_dividend) {
            // No filtering active: use the aggregate daily_dividend
            dividend = item.daily_dividend;
        }

        const dividendNum = Number(dividend) || 0;
        if (dividendNum !== 0) {
            dividendMap.set(item.date, dividendNum);
        }
    }

    if (dividendMap.size === 0) {
        return contributionSeries;
    }

    // Clone the series so we don't mutate the original
    const merged = new Array(contributionSeries.length);
    for (let i = 0; i < contributionSeries.length; i++) {
        merged[i] = { ...contributionSeries[i] };
    }

    // Build a Map of dateStr → index from contributionSeries for quick lookup
    const seriesMap = new Map();
    for (let i = 0; i < merged.length; i++) {
        seriesMap.set(merged[i].tradeDate, i);
    }

    // Process each dividend entry
    for (const [dateStr, dividend] of dividendMap.entries()) {
        const convertedDividend =
            currency && currency !== 'USD'
                ? convertValueToCurrency(dividend, dateStr, currency)
                : dividend;

        if (seriesMap.has(dateStr)) {
            // Date already exists in contribution series: add sellVolume, mark dividend delta
            const idx = seriesMap.get(dateStr);
            merged[idx].sellVolume = (merged[idx].sellVolume || 0) + convertedDividend;
            merged[idx].netAmount = (merged[idx].netAmount || 0) - convertedDividend;
        } else {
            // Insert a new point for this dividend date
            merged.push({
                tradeDate: dateStr,
                amount: 0, // will be recalculated
                value: 0,
                orderType: 'sell',
                netAmount: -convertedDividend,
                buyVolume: 0,
                sellVolume: convertedDividend,
            });
        }
    }

    // Re-sort by date
    merged.sort((a, b) => (a.tradeDate < b.tradeDate ? -1 : a.tradeDate > b.tradeDate ? 1 : 0));

    // Recalculate cumulative amounts
    let cumulative = 0;
    for (let i = 0; i < merged.length; i++) {
        const point = merged[i];
        cumulative += point.netAmount;
        point.amount = cumulative;
        point.value = cumulative;
    }

    return merged;
}

import { CHART_SMOOTHING } from '../../config.js';
import { logger } from '../../utils/logger.js';

// Bolt: Cache Intl.DateTimeFormat instance to prevent expensive recreation
const getCrosshairDateFormatter = (() => {
    let formatter = null;
    return () => {
        if (!formatter && typeof Intl !== 'undefined') {
            formatter = new Intl.DateTimeFormat('en-US', {
                year: 'numeric',
                month: 'short',
                day: '2-digit',
            });
        }
        return formatter;
    };
})();

const DEFAULT_MONO_FONT = "'JetBrains Mono','IBM Plex Mono','Menlo',monospace";

// Color parsing context
const COLOR_PARSER_CONTEXT = (() => {
    if (typeof document === 'undefined') {
        return null;
    }
    const canvas = document.createElement('canvas');
    canvas.width = 1;
    canvas.height = 1;
    return canvas.getContext('2d');
})();

function _getRoundedNiceFraction(fraction) {
    if (fraction < 1.5) {
        return 1;
    }
    if (fraction < 3) {
        return 2;
    }
    if (fraction < 7) {
        return 5;
    }
    return 10;
}

function _getExactNiceFraction(fraction) {
    if (fraction <= 1) {
        return 1;
    }
    if (fraction <= 2) {
        return 2;
    }
    if (fraction <= 5) {
        return 5;
    }
    return 10;
}

export function niceNumber(range, round) {
    if (!Number.isFinite(range) || range === 0) {
        return 1;
    }
    const exponent = Math.floor(Math.log10(Math.abs(range)));
    const fraction = Math.abs(range) / 10 ** exponent;

    const niceFraction = round
        ? _getRoundedNiceFraction(fraction)
        : _getExactNiceFraction(fraction);

    return (range < 0 ? -1 : 1) * niceFraction * 10 ** exponent;
}

export function parseLocalDate(value) {
    if (value instanceof Date) {
        return new Date(value.getFullYear(), value.getMonth(), value.getDate());
    }
    if (typeof value === 'number') {
        const temp = new Date(value);
        if (!Number.isNaN(temp.getTime())) {
            return new Date(temp.getFullYear(), temp.getMonth(), temp.getDate());
        }
        return null;
    }
    if (typeof value === 'string') {
        const parts = value.split('-');
        if (parts.length >= 3) {
            const year = Number(parts[0]);
            const month = Number(parts[1]) - 1;
            const day = Number(parts[2]);
            if (Number.isFinite(year) && Number.isFinite(month) && Number.isFinite(day)) {
                return new Date(year, month, day);
            }
        }
        const parsed = new Date(value);
        if (!Number.isNaN(parsed.getTime())) {
            return new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
        }
    }
    return null;
}

export function clampTime(value, min, max) {
    if (!Number.isFinite(value)) {
        return min;
    }
    if (!Number.isFinite(min) || !Number.isFinite(max)) {
        return value;
    }
    if (value < min) {
        return min;
    }
    if (value > max) {
        return max;
    }
    return value;
}

export function createTimeInterpolator(points) {
    if (!Array.isArray(points) || points.length === 0) {
        return () => null;
    }
    const sorted = points.slice().sort((a, b) => a.time - b.time);
    return (time) => {
        if (!Number.isFinite(time)) {
            return null;
        }
        const clampedTime = clampTime(time, sorted[0].time, sorted[sorted.length - 1].time);
        let low = 0;
        let high = sorted.length - 1;
        while (low <= high) {
            const mid = Math.floor((low + high) / 2);
            const midTime = sorted[mid].time;
            if (midTime === clampedTime) {
                return sorted[mid].value;
            }
            if (midTime < clampedTime) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        const leftIndex = Math.max(0, Math.min(sorted.length - 1, high));
        const rightIndex = Math.max(0, Math.min(sorted.length - 1, low));
        const leftPoint = sorted[leftIndex];
        const rightPoint = sorted[rightIndex] || leftPoint;
        if (!leftPoint || !rightPoint) {
            return null;
        }
        if (leftPoint.time === rightPoint.time) {
            return leftPoint.value;
        }
        const ratio = (clampedTime - leftPoint.time) / (rightPoint.time - leftPoint.time || 1e-12);
        return leftPoint.value + (rightPoint.value - leftPoint.value) * ratio;
    };
}

export function getMonoFontFamily() {
    if (typeof window !== 'undefined' && window.getComputedStyle) {
        const value = window
            .getComputedStyle(document.documentElement)
            .getPropertyValue('--font-family-mono');
        if (value && value.trim()) {
            return value.trim();
        }
    }
    return DEFAULT_MONO_FONT;
}

export const formatPercentInline = (value) => {
    if (!Number.isFinite(value)) {
        return '0%';
    }
    const sign = value > 0 ? '+' : value < 0 ? '−' : '';
    return `${sign}${Math.abs(value).toFixed(2)}%`;
};

export function formatFxValue(value) {
    if (!Number.isFinite(value)) {
        return '–';
    }
    const absValue = Math.abs(value);
    if (absValue >= 100) {
        return value.toFixed(1);
    }
    if (absValue >= 10) {
        return value.toFixed(2);
    }
    if (absValue >= 1) {
        return value.toFixed(3);
    }
    return value.toFixed(4);
}

export function formatCrosshairDateLabel(time) {
    if (!Number.isFinite(time)) {
        return '';
    }
    const date = new Date(time);
    if (Number.isNaN(date.getTime())) {
        return '';
    }
    const formatter = getCrosshairDateFormatter();
    if (formatter) {
        return formatter.format(date);
    }
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${date.getFullYear()}-${month}-${day}`;
}

// Color Utility Functions
export function clamp01(value) {
    if (!Number.isFinite(value)) {
        return 0;
    }
    return Math.min(1, Math.max(0, value));
}

function componentFromChannel(channel) {
    const trimmed = channel.trim();
    if (trimmed.endsWith('%')) {
        const percentage = parseFloat(trimmed.slice(0, -1));
        if (!Number.isFinite(percentage)) {
            return 0;
        }
        return Math.round((percentage / 100) * 255);
    }
    const numeric = parseFloat(trimmed);
    return Number.isFinite(numeric) ? Math.round(numeric) : 0;
}

function extractHexComponents(hexStr) {
    let hex = hexStr;
    if (hex.length === 3) {
        hex = hex
            .split('')
            .map((char) => char + char)
            .join('');
    }
    const intVal = parseInt(hex, 16);
    return {
        r: (intVal >> 16) & 255,
        g: (intVal >> 8) & 255,
        b: intVal & 255,
    };
}

function extractRgbComponents(rgbStr) {
    const parts = rgbStr.split(',');
    if (parts.length >= 3) {
        return {
            r: componentFromChannel(parts[0]),
            g: componentFromChannel(parts[1]),
            b: componentFromChannel(parts[2]),
        };
    }
    return null;
}

function resolveCanvasColor(baseColor) {
    if (!COLOR_PARSER_CONTEXT) {
        return null;
    }

    const ctx = COLOR_PARSER_CONTEXT;
    ctx.save();
    try {
        ctx.fillStyle = '#000000';
        ctx.fillStyle = baseColor;
        const computed1 = ctx.fillStyle;

        ctx.fillStyle = '#ffffff';
        ctx.fillStyle = baseColor;
        const computed2 = ctx.fillStyle;

        ctx.restore();

        if (computed1 !== computed2) {
            return null;
        }

        if (computed1 && computed1 !== baseColor) {
            return parseColorToRgb(computed1);
        }
    } catch (error) {
        logger.warn('Chart helpers execution failed:', error);
        ctx.restore();
        return null;
    }
    return null;
}

export function parseColorToRgb(baseColor) {
    if (typeof baseColor !== 'string' || baseColor.length === 0) {
        return null;
    }

    const hexMatch = baseColor.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
    if (hexMatch) {
        return extractHexComponents(hexMatch[1]);
    }

    const rgbMatch = baseColor.match(/^rgba?\(([^)]+)\)$/i);
    if (rgbMatch) {
        const rgb = extractRgbComponents(rgbMatch[1]);
        if (rgb) {
            return rgb;
        }
    }

    return resolveCanvasColor(baseColor);
}

function _applyAlphaToHex(match, alpha) {
    let hex = match[1];
    if (hex.length === 3) {
        hex = hex
            .split('')
            .map((char) => char + char)
            .join('');
    }
    const intVal = parseInt(hex, 16);
    const r = (intVal >> 16) & 255;
    const g = (intVal >> 8) & 255;
    const b = intVal & 255;
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function _applyAlphaToRgb(match, alpha) {
    const parts = match[1].split(',');
    if (parts.length >= 3) {
        const r = componentFromChannel(parts[0]);
        const g = componentFromChannel(parts[1]);
        const b = componentFromChannel(parts[2]);
        return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    }
    return null;
}

function _applyAlphaToCanvasColor(baseColor, alpha) {
    if (COLOR_PARSER_CONTEXT) {
        const ctx = COLOR_PARSER_CONTEXT;
        ctx.save();
        ctx.fillStyle = baseColor;
        const computed = ctx.fillStyle;
        ctx.restore();
        if (computed && computed !== baseColor) {
            return colorWithAlpha(computed, alpha);
        }
    }
    return null;
}

export function colorWithAlpha(baseColor, alpha) {
    const normalizedAlpha = clamp01(alpha);
    if (normalizedAlpha <= 0) {
        return 'rgba(0, 0, 0, 0)';
    }

    if (typeof baseColor !== 'string' || baseColor.length === 0) {
        return baseColor;
    }

    const hexMatch = baseColor.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
    if (hexMatch) {
        return _applyAlphaToHex(hexMatch, normalizedAlpha);
    }

    const rgbMatch = baseColor.match(/^rgba?\(([^)]+)\)$/i);
    if (rgbMatch) {
        const rgbColor = _applyAlphaToRgb(rgbMatch, normalizedAlpha);
        if (rgbColor) {
            return rgbColor;
        }
    }

    const canvasColor = _applyAlphaToCanvasColor(baseColor, normalizedAlpha);
    if (canvasColor) {
        return canvasColor;
    }

    return baseColor;
}

export function lightenColor(baseColor, amount = 0.3) {
    const components = parseColorToRgb(baseColor);
    if (!components) {
        return baseColor;
    }
    const ratio = clamp01(amount);
    const mixChannel = (value) => Math.round(value + (255 - value) * ratio);
    const r = mixChannel(components.r);
    const g = mixChannel(components.g);
    const b = mixChannel(components.b);
    return `rgb(${r}, ${g}, ${b})`;
}

export function darkenColor(baseColor, amount = 0.3) {
    const components = parseColorToRgb(baseColor);
    if (!components) {
        return baseColor;
    }
    const ratio = clamp01(amount);
    const mixChannel = (value) => Math.round(value * (1 - ratio));
    const r = mixChannel(components.r);
    const g = mixChannel(components.g);
    const b = mixChannel(components.b);
    return `rgb(${r}, ${g}, ${b})`;
}

export function getChartColors(rootStyles) {
    if (!rootStyles) {
