export function getSmoothingConfig(chartType) {
    if (!CHART_SMOOTHING.enabled) {
        return null; // Smoothing disabled
    }

    const methodName = CHART_SMOOTHING.charts[chartType] || 'balanced';
    const methodConfig = CHART_SMOOTHING.methods[methodName] || CHART_SMOOTHING.methods.balanced;
    if (!methodConfig || methodConfig.method === 'none') {
        return null;
    }
    return methodConfig;
}

function _extractFirstFilteredTime(filteredData) {
    if (!Array.isArray(filteredData) || filteredData.length === 0) {
        return null;
    }
    const firstFiltered = filteredData[0];
    const firstTime =
        firstFiltered && firstFiltered.date instanceof Date
            ? firstFiltered.date.getTime()
            : new Date(firstFiltered.date).getTime();
    return Number.isFinite(firstTime) ? firstTime : null;
}

function _findMatchingIndex(fullSeries, firstTime) {
    if (!Array.isArray(fullSeries) || fullSeries.length === 0) {
        return -1;
    }
    return fullSeries.findIndex((item) => {
        if (!item) {
            return false;
        }
        const itemDate = new Date(item.date);
        return !Number.isNaN(itemDate.getTime()) && itemDate.getTime() === firstTime;
    });
}

function _createClampedPoint(previousPoint, filterFrom, firstTime) {
    if (Math.abs(firstTime - filterFrom.getTime()) < 1000) {
        return null;
    }
    return {
        ...previousPoint,
        date: new Date(filterFrom),
        synthetic: true,
    };
}

function _createStandardSyntheticPoint(previousPoint, prevDate, filteredData, filterFrom) {
    const prevValue = Number(previousPoint.value);
    const epsilon = 1e-6;
    if (!Number.isFinite(prevValue) || Math.abs(prevValue) > epsilon) {
        return null;
    }

    if (
        filteredData[0].date instanceof Date &&
        filteredData[0].date.getTime() === prevDate.getTime()
    ) {
        return null;
    }

    if (filterFrom && prevDate < filterFrom) {
        return null;
    }

    return {
        date: prevDate,
        value: Number.isFinite(prevValue) ? prevValue : 0,
        synthetic: true,
    };
}

function _processSyntheticPoint(previousPoint, filterFrom, firstTime, filteredData) {
    const prevDate = new Date(previousPoint.date);
    if (Number.isNaN(prevDate.getTime())) {
        return null;
    }

    if (filterFrom && prevDate < filterFrom) {
        const clampedPoint = _createClampedPoint(previousPoint, filterFrom, firstTime);
        return clampedPoint ? [clampedPoint, ...filteredData] : null;
    }

    const standardPoint = _createStandardSyntheticPoint(
        previousPoint,
        prevDate,
        filteredData,
        filterFrom
    );
    return standardPoint ? [standardPoint, ...filteredData] : null;
}

export function injectSyntheticStartPoint(filteredData, fullSeries, filterFrom = null) {
    const firstTime = _extractFirstFilteredTime(filteredData);
    if (firstTime === null) {
        return filteredData;
    }

    const matchingIndex = _findMatchingIndex(fullSeries, firstTime);
    if (matchingIndex <= 0) {
        return filteredData;
    }

    const previousPoint = fullSeries[matchingIndex - 1];
    if (!previousPoint || !previousPoint.synthetic) {
        return filteredData;
    }

    const result = _processSyntheticPoint(previousPoint, filterFrom, firstTime, filteredData);
    return result || filteredData;
}

/**
 * Injects a carry-forward point at the filter start date for cumulative series like contribution.
 * If the filter starts after the first data point and there's history before the filter,
 * this will inject a point at filterFrom with the last value before the filter range.
 */
export function injectCarryForwardStartPoint(
    filteredData,
    fullSeries,
    filterFrom,
    valueKey = 'value'
) {
    if (!filterFrom || !Array.isArray(filteredData)) {
        return filteredData;
    }
    if (!Array.isArray(fullSeries) || fullSeries.length === 0) {
        return filteredData;
    }

    const filterFromTime = filterFrom.getTime();
    if (!Number.isFinite(filterFromTime)) {
        return filteredData;
    }

    // Find the last point in fullSeries that is before filterFrom
    let lastPointBeforeFilter = null;
    for (let i = fullSeries.length - 1; i >= 0; i--) {
        const item = fullSeries[i];
        if (!item) {
            continue;
        }
        const itemDate = new Date(item.date);
        if (Number.isNaN(itemDate.getTime())) {
            continue;
        }
        if (itemDate.getTime() < filterFromTime) {
            lastPointBeforeFilter = item;
            break;
        }
    }

    if (!lastPointBeforeFilter) {
        return filteredData;
    }

    // Check if first filtered point is at or before filterFrom (no need to inject)
    if (filteredData.length > 0) {
        const firstFiltered = filteredData[0];
        const firstFilteredDate =
            firstFiltered.date instanceof Date ? firstFiltered.date : new Date(firstFiltered.date);
        if (firstFilteredDate.getTime() <= filterFromTime) {
            return filteredData;
        }
    }

    // Inject a carry-forward point at filterFrom with the last value before filter
    const carryForwardValue = Number(lastPointBeforeFilter[valueKey]);
    if (!Number.isFinite(carryForwardValue)) {
        return filteredData;
    }

    const carryForwardPoint = {
        ...lastPointBeforeFilter,
        date: new Date(filterFrom),
        [valueKey]: carryForwardValue,
        synthetic: true,
        carryForward: true,
    };

    return [carryForwardPoint, ...filteredData];
}

export function constrainSeriesToRange(series, rangeStart, rangeEnd) {
    if (!Array.isArray(series) || (!rangeStart && !rangeEnd)) {
        return series;
    }

    const startTime =
        rangeStart instanceof Date && Number.isFinite(rangeStart.getTime())
            ? rangeStart.getTime()
            : null;
    const endTime =
        rangeEnd instanceof Date && Number.isFinite(rangeEnd.getTime()) ? rangeEnd.getTime() : null;

    if (!Number.isFinite(startTime) && !Number.isFinite(endTime)) {
        return series;
    }

    return series.filter((point) => {
        if (!point) {
            return false;
        }
        const pointDate = point.date instanceof Date ? point.date : new Date(point.date);
        const time = pointDate.getTime();
        if (Number.isNaN(time)) {
            return false;
        }
        if (Number.isFinite(startTime) && time < startTime) {
            return false;
        }
        if (Number.isFinite(endTime) && time > endTime) {
            return false;
        }
        return true;
    });
}

import { transactionState } from '../state.js';
