const THINKING_REGISTRY = new WeakMap();

function getWindow() {
    return typeof window !== 'undefined' ? window : null;
}

function scheduleFrame(callback) {
    const w = getWindow();
    if (w && typeof w.requestAnimationFrame === 'function') {
        return w.requestAnimationFrame(callback);
    }
    return setTimeout(() => callback(Date.now()), 16);
}

function cancelFrame(handle) {
    const w = getWindow();
    if (w && typeof w.cancelAnimationFrame === 'function') {
        w.cancelAnimationFrame(handle);
    } else {
        clearTimeout(handle);
    }
}

function prefersReducedMotion() {
    const w = getWindow();
    if (!w || typeof w.matchMedia !== 'function') {
        return false;
    }
    try {
        return w.matchMedia('(prefers-reduced-motion: reduce)').matches;
    } catch (error) {
        // eslint-disable-next-line no-console
        console.warn('Text highlight reduced motion check failed:', error);
        return false;
    }
}

function normalizeTargets(target) {
    if (!target) {
        return [];
    }

    if (Array.isArray(target)) {
        const nodes = [];
        for (let i = 0; i < target.length; i++) {
            nodes.push(...normalizeTargets(target[i]));
        }
        return nodes;
    }

    if (typeof target.each === 'function') {
        const nodes = [];
        target.each(function collectNodes() {
            if (this && this.nodeType === 1) {
                nodes.push(this);
            }
        });
        return nodes;
    }

    if (typeof target.node === 'function') {
        const node = target.node();
        return node ? [node] : [];
    }

    if (target.nodeType === 1) {
        return [target];
    }

    return [];
}

/**
 * Applies or removes the shimmer highlight class from the provided target(s).
 * The function accepts DOM elements, d3 selections, or arrays of DOM elements.
 *
 * @param {Element|Array<Element>|Object} target - Target node(s) or d3 selection.
 * @param {boolean} shouldHighlight - When true the highlight class is added, otherwise removed.
 * @param {object} [options]
 * @param {string} [options.className='text-shimmer'] - CSS class to toggle.
 */
export function setHighlightState(target, shouldHighlight, options = DEFAULT_OPTIONS) {
    const { className = DEFAULT_OPTIONS.className } = options || DEFAULT_OPTIONS;
    const nodes = normalizeTargets(target);

    for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i];
        if (!node || !node.classList) {
            continue;
        }
        if (shouldHighlight) {
            node.classList.add(className);
        } else {
            node.classList.remove(className);
        }
    }
}

/**
 * Convenience helper to apply both foreground (text) and background shimmer highlights.
 *
 * @param {Element|Array<Element>|Object} textTarget
 * @param {Element|Array<Element>|Object} backgroundTarget
 * @param {boolean} shouldHighlight
 */
export function setCompositeHighlight(textTarget, backgroundTarget, shouldHighlight) {
    setHighlightState(textTarget, shouldHighlight, { className: 'text-shimmer' });
    setHighlightState(backgroundTarget, shouldHighlight, { className: 'text-shimmer-bg' });
}

export const HIGHLIGHT_CLASSES = Object.freeze({
    text: 'text-shimmer',
    background: 'text-shimmer-bg',
});

function createCharacterNodes(node, baseText, baseColor) {
    const characters = Array.from(baseText);
    const created = [];
    node.textContent = '';
    const fragment = node.ownerDocument.createDocumentFragment();

    // Check if this is an SVG element
    const isSvg = node.namespaceURI === SVG_NS || node.closest('svg') !== null;

    for (let index = 0; index < characters.length; index++) {
        const char = characters[index];
        let child;
        if (isSvg) {
            // Create SVG tspan element
            child = node.ownerDocument.createElementNS(SVG_NS, 'tspan');
            child.setAttribute('fill', baseColor);
            child.setAttribute('data-thinking-base-fill', baseColor);
        } else {
            // Create HTML span element
            child = node.ownerDocument.createElement('span');
            child.style.color = baseColor;
            child.setAttribute('data-thinking-base-color', baseColor);
        }

        child.textContent = char;
        child.setAttribute('class', 'text-thinking-char');
        child.setAttribute('data-thinking-index', String(index));
        fragment.appendChild(child);
        created.push(child);
    }
    node.appendChild(fragment);
    return created;
}

function mergeThinkingOptions(options) {
    if (!options) {
        return { ...DEFAULT_THINKING_CONFIG };
    }
    return { ...DEFAULT_THINKING_CONFIG, ...options };
}

function createThinkingEntry(node, baseText, options) {
    const baseFillAttr = node.getAttribute('fill');
    const baseStyleFill = node.style ? node.style.fill : undefined;
    const baseStyleColor = node.style ? node.style.color : undefined;
    const baseColor = baseFillAttr || baseStyleFill || baseStyleColor || options.baseColor;

    const charNodes = createCharacterNodes(node, baseText, baseColor);
    if (!charNodes.length) {
        return null;
    }

    node.setAttribute('data-thinking-active', 'true');
    return {
        nodeState: { node, baseText, baseFillAttr, baseStyleFill, baseStyleColor },
        charNodes,
    };
}

function applyThinkingWave(entry) {
    const { charNodes, options: opts } = entry;
    const { dimColor, waveSize: size } = opts;
    const total = charNodes.length;
    for (let i = 0; i < total; i += 1) {
        const distance = (i - entry.currentIndex + total) % total;
        const isSvg = charNodes[i].getAttribute('data-thinking-base-fill') !== null;
        const baseColor = isSvg
            ? charNodes[i].getAttribute('data-thinking-base-fill') || opts.baseColor
            : charNodes[i].getAttribute('data-thinking-base-color') || opts.baseColor;
        const targetColor = distance < size ? dimColor : baseColor;
        if (isSvg) {
            charNodes[i].setAttribute('fill', targetColor);
        } else {
            charNodes[i].style.color = targetColor;
        }
    }
    entry.currentIndex = (entry.currentIndex + 1) % total;
}

function scheduleThinkingFrame(entry) {
    function frame(timestamp) {
        if (entry.destroyed) {
            return;
        }

        let isConnected = true;
        if (entry.isGroup) {
            const primary = entry.nodes[0]?.node;
            isConnected = primary && primary.isConnected;
        } else {
            isConnected = entry.node.isConnected;
        }

        if (!isConnected) {
            if (entry.isGroup) {
                for (let i = 0; i < entry.nodes.length; i++) {
                    stopThinking(entry.nodes[i].node);
                }
            } else {
                stopThinking(entry.node);
            }
            return;
        }

        if (!entry.lastTimestamp) {
            entry.lastTimestamp = timestamp;
        }
        if (timestamp - entry.lastTimestamp >= entry.options.intervalMs) {
            entry.lastTimestamp = timestamp;
            applyThinkingWave(entry);
        }
        entry.frameId = scheduleFrame(frame);
    }
    entry.frameId = scheduleFrame(frame);
}

function startThinking(node, options) {
    if (!node || node.nodeType !== 1) {
        return;
    }
    if (THINKING_REGISTRY.get(node)) {
        stopThinking(node);
    }

    const mergedOptions = mergeThinkingOptions(options);
    const baseText = node.textContent || '';
    if (!baseText) {
        return;
    }

    const result = createThinkingEntry(node, baseText, mergedOptions);
    if (!result) {
        return;
    }

    mergedOptions.waveSize = Math.max(
        1,
        Math.min(mergedOptions.waveSize || 1, result.charNodes.length)
    );

    const entry = {
        ...result.nodeState,
        options: mergedOptions,
        charNodes: result.charNodes,
        frameId: null,
        currentIndex: 0,
        lastTimestamp: 0,
        destroyed: false,
        nodes: null,
    };

    applyThinkingWave(entry);
    THINKING_REGISTRY.set(node, entry);

    if (!(mergedOptions.disableAnimation || prefersReducedMotion())) {
        scheduleThinkingFrame(entry);
    }
}

function startThinkingGroup(nodes, options) {
    const mergedOptions = mergeThinkingOptions(options);
    const validNodes = nodes.filter((node) => node && node.nodeType === 1);
    if (!validNodes.length) {
        return;
    }

    for (let i = 0; i < validNodes.length; i++) {
        const node = validNodes[i];
        if (THINKING_REGISTRY.get(node)) {
            stopThinking(node);
        }
    }

    const nodeStates = [];
    const charNodes = [];

    for (let i = 0; i < validNodes.length; i++) {
        const node = validNodes[i];
        const baseText = node.textContent || '';
        if (!baseText) {
            continue;
        }
        const result = createThinkingEntry(node, baseText, mergedOptions);
        if (result) {
            nodeStates.push(result.nodeState);
            charNodes.push(...result.charNodes);
        }
    }

    if (!charNodes.length) {
        return;
    }
    mergedOptions.waveSize = Math.max(1, Math.min(mergedOptions.waveSize || 1, charNodes.length));

    const entry = {
        nodes: nodeStates,
        options: mergedOptions,
        charNodes,
        frameId: null,
        currentIndex: 0,
        lastTimestamp: 0,
        destroyed: false,
        isGroup: true,
    };

    for (let i = 0; i < nodeStates.length; i++) {
        THINKING_REGISTRY.set(nodeStates[i].node, entry);
    }
    applyThinkingWave(entry);

    if (!(mergedOptions.disableAnimation || prefersReducedMotion())) {
        scheduleThinkingFrame(entry);
    }
}

function resetThinkingNodeAttributes(state) {
    state.node.textContent = state.baseText || '';
    if (state.baseFillAttr !== null && state.baseFillAttr !== undefined) {
        state.node.setAttribute('fill', state.baseFillAttr);
    } else {
        state.node.removeAttribute('fill');
    }
}

function resetThinkingNodeStyles(state) {
    if (!state.node.style) {
        return;
    }
    if (state.baseStyleFill !== undefined) {
        state.node.style.fill = state.baseStyleFill;
    } else {
        state.node.style.fill = '';
    }
    if (state.baseStyleColor !== undefined) {
        state.node.style.color = state.baseStyleColor;
    } else if (!state.baseFillAttr) {
        // Only clear color if there's no SVG fill attribute
        state.node.style.color = '';
    }
}

function stopThinkingState(state) {
    if (!state || !state.node) {
        return;
    }
    resetThinkingNodeAttributes(state);
    resetThinkingNodeStyles(state);
    state.node.removeAttribute('data-thinking-active');
    THINKING_REGISTRY.delete(state.node);
}

function stopThinking(node) {
    const entry = THINKING_REGISTRY.get(node);
    if (!entry) {
        return;
    }
    entry.destroyed = true;
    if (entry.frameId !== null) {
        cancelFrame(entry.frameId);
    }

    const states = entry.nodes || [
        {
            node: entry.node,
            baseText: entry.baseText,
            baseFillAttr: entry.baseFillAttr,
            baseStyleFill: entry.baseStyleFill,
            baseStyleColor: entry.baseStyleColor,
        },
    ];

    for (let i = 0; i < states.length; i++) {
        stopThinkingState(states[i]);
    }
}

/**
 * Applies a sequential "thinking" highlight where letters dim in a wave pattern.
 *
 * @param {Element|Array<Element>|Object} target
 * @param {boolean} shouldHighlight
 * @param {object} [options]
 */
export function setThinkingHighlight(target, shouldHighlight, options = null) {
    if (Array.isArray(target)) {
        const nodes = normalizeTargets(target);
        if (!nodes.length) {
            return;
        }
        if (shouldHighlight) {
            startThinkingGroup(nodes, options || undefined);
        } else {
            for (let i = 0; i < nodes.length; i++) {
                stopThinking(nodes[i]);
            }
        }
        return;
    }

    const nodes = normalizeTargets(target);
    for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i];
        if (!node || node.nodeType !== 1) {
            continue;
        }
        if (shouldHighlight) {
            startThinking(node, options || undefined);
        } else {
            stopThinking(node);
        }
    }
}
